import{d as I,C as l,o as K,c as N,j as a,a as n,E as i,a3 as s}from"./chunks/framework.Q4yG9rk_.js";const Y=JSON.parse('{"title":"庄子·寓言","description":"从寓言、重言与卮言入手，理解言说的接受障碍、权威依据，以及判断与万物变化之间的关系。","frontmatter":{"title":"庄子·寓言","description":"从寓言、重言与卮言入手，理解言说的接受障碍、权威依据，以及判断与万物变化之间的关系。","category":"guide","aliases":["寓言","庄子寓言","zhuangzi chapter 27"],"source":["《庄子·杂篇·寓言》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-27.md","filePath":"daoism/zhuang-zi/chapter-27.md","lastUpdated":1792641266000}'),R={name:"daoism/zhuang-zi/chapter-27.md"},Z=I({...R,setup(G){const y=[{id:"yuyan-yuyan",term:"寓言",pinyin:"yù yán",meaning:"寄寓之言，借外在人物、他者或情境来论说。另：不只指现代文学中的寓意故事，也不要求每个故事都以明确教训作结。"},{id:"yuyan-shijiu",term:"十九",pinyin:"shí jiǔ",meaning:"通常理解为十之九，表示使用多、比例高。另：不是十九则；也不宜据此统计全书篇幅。"},{id:"yuyan-zhongyan",term:"重言",pinyin:"zhòng yán",meaning:"有分量的言说，通常联系借前人、长者或受尊重者之言来论说。另：不是简单重复同一句话；所借重的分量仍需要实际识见支撑。"},{id:"yuyan-shiqi",term:"十七",pinyin:"shí qī",meaning:"通常理解为十之七，表示作用或使用之广。另：不是十七则；寓言与重言并非互斥分类，十九与十七不能直接相加。"},{id:"yuyan-zhiyan",term:"卮言",pinyin:"zhī yán",meaning:"可理解为不固执于一定判断、随情境变化而展开的言说。另：“卮”为古代盛酒器具，注释常借器物倾满变化的意象说明卮言；这一比喻不能代替对整段语境的理解。"},{id:"yuyan-richu",term:"日出",pinyin:"rì chū",meaning:"日日生出、不断出现。另：此处不必按太阳升起理解。"},{id:"yuyan-heyi-tianni",term:"和以天倪",pinyin:"hé yǐ tiān ní",meaning:"以自然的分际、端绪或条理相调和。另：可理解为不完全由人为成见强加尺度；“和”不必等于所有意见完全一致。"},{id:"yuyan-jiewai",term:"藉外论之",pinyin:"jiè wài lùn zhī",meaning:"借外在人物或他者来论说；藉，借助。另：改变表达的位置，不等于作者没有立场，也不等于故事人物的每句话都是作者的最终判断。"},{id:"yuyan-qinfu",term:"亲父",pinyin:"qīn fù",meaning:"生父、亲生父亲。"},{id:"yuyan-weizi-mei",term:"为其子媒",pinyin:"wèi qí zǐ méi",meaning:"替自己的儿子作媒。另：本段借此说明听者对说话者关系与立场的顾虑，不宜视为普遍婚姻规定。"},{id:"yuyan-yuzhi",term:"誉之",pinyin:"yù zhī",meaning:"称赞他。"},{id:"yuyan-zui",term:"罪",pinyin:"zuì",meaning:"此处指过失、问题所在。另：不是现代法律意义上的犯罪。"},{id:"yuyan-tongze-ying",term:"与己同则应",pinyin:"yǔ jǐ tóng zé yìng",meaning:"与自己的意见相同，便响应、赞同。"},{id:"yuyan-butongze-fan",term:"不与己同则反",pinyin:"bù yǔ jǐ tóng zé fǎn",meaning:"与自己的意见不同，便反对。"},{id:"yuyan-shizhi-feizhi",term:"是之·非之",pinyin:"shì zhī · fēi zhī",meaning:"认定它正确、认定它错误。另：这里讨论的是认定的方式，不宜把“与我相同”直接当作正确的充分根据。"},{id:"yuyan-suoyi-jiyan",term:"所以己言也",pinyin:"suǒ yǐ jǐ yán yě",meaning:"“己”常被按“已”解释，有止息义；可理解为借重言止息纷纭争言。另：训释存在分歧。“己”字照录所供原文，不直接改字；这也不是说借来权威便可以终止一切讨论。"},{id:"yuyan-qiai",term:"耆艾",pinyin:"qí ài",meaning:"老年人、年高而受尊重者。另：古代年龄称谓中，常以六十称耆、五十称艾；具体用法仍需结合语境。"},{id:"yuyan-nianxian",term:"年先矣",pinyin:"nián xiān yǐ",meaning:"年龄在先，比别人年长。另：年龄在先与识见在先，不能直接等同。"},{id:"yuyan-jingwei",term:"经纬",pinyin:"jīng wěi",meaning:"原指纵横的线，引申为条理、组织与贯通的识见。"},{id:"yuyan-benmo",term:"本末",pinyin:"běn mò",meaning:"根本与枝末，事物的源流与层次。"},{id:"yuyan-yiqi-nianqi",term:"以期年耆",pinyin:"句读及相关训释待辨",meaning:"句法有疑义，可联系识见是否与其年长相称来理解。另：不宜把这里的“期年”机械解释为“满一年”，也不据此强定整句唯一译法。"},{id:"yuyan-shifeixian",term:"是非先也",pinyin:"shì fēi xiān yě",meaning:"这样便不是真正在先。另：“是”为指示词；这里不是把“是非”连读为是非判断。"},{id:"yuyan-wuyi-xianren",term:"无以先人",pinyin:"wú yǐ xiān rén",meaning:"没有什么识见、德行等足以在人之前。另：不是“没有祖先”，也不宜引申为每个人都必须在成就上胜过别人。"},{id:"yuyan-wurendao",term:"无人道",pinyin:"wú rén dào",meaning:"缺乏相应的为人之道。另：联系本段，主要是对徒有年齿而无实际识见者的批评，不宜扩大为对人的生命价值进行排名。"},{id:"yuyan-chenren",term:"陈人",pinyin:"chén rén",meaning:"陈旧之人，可理解为徒有年岁积累而无相应通达者。另：带有强烈批评意味；批评的重点是积久而未通，不是年老本身。"},{id:"yuyan-tianni",term:"天倪",pinyin:"tiān ní",meaning:"自然的分际、端绪或条理；倪有端、际义。另：具体哲学解释存在差异，不宜把它固定为单一现代概念。"},{id:"yuyan-manyan",term:"因以曼衍",pinyin:"yīn yǐ màn yǎn",meaning:"因循情境而展开、延伸；曼衍有绵延、铺展义。另：强调有所顺应，不等于随意改口或一味迎合。"},{id:"yuyan-qiongnian",term:"穷年",pinyin:"qióng nián",meaning:"尽其年岁、终其一生。另：不是年岁贫困。"},{id:"yuyan-qi",term:"齐",pinyin:"qí",meaning:"齐同、齐一，此处与语言形成的分别相对照。另：相关句子训释不一；不能据“不言则齐”断言沉默永远优于言说。"},{id:"yuyan-yanwuyan",term:"言无言",pinyin:"yán wú yán",meaning:"可理解为言说而不执着于言说，不以言辞封闭对象。另：不能只按“不出声”理解；这里是贯通上下文的一种解释，并非唯一逐字定译。"},{id:"yuyan-youzi",term:"有自也",pinyin:"yǒu zì yě",meaning:"有其所从，有一定根据或出发点。另：“自”不是简单的“自己”；有出发点也不等于具有充分根据。"},{id:"yuyan-ke-buke",term:"可·不可",pinyin:"kě · bù kě",meaning:"可接受、可认可与不可接受、不可认可。另：具体意义随语境而定，不宜直接等同于一切行为的伦理许可。"},{id:"yuyan-ran-buran",term:"然·不然",pinyin:"rán · bù rán",meaning:"被认定为如此、正确，与被认定为不如此、不正确。另：本段侧重判断的成立及其所从。"},{id:"yuyan-wuhu",term:"恶乎",pinyin:"wū hū",meaning:"从哪里、为什么。另：“恶”在此读 wū，不是善恶之恶。"},{id:"yuyan-yousuoran-ke",term:"有所然·有所可",pinyin:"yǒu suǒ rán · yǒu suǒ kě",meaning:"有被认作如此、被认可的方面或根据。另：“有所”限定了理解的角度与关系，不等于所有判断都正确、所有行为都正当。"},{id:"yuyan-shudeqijiu",term:"孰得其久",pinyin:"shú dé qí jiǔ",meaning:"谁能使之长久、保持长久的相应？。另：与前面的“非”构成反问。“其”的所指需结合上下文理解，“久”不宜径释为肉身长生。"},{id:"yuyan-wanwu-jiezhong",term:"万物皆种",pinyin:"wàn wù jiē zhǒng",meaning:"涉及万物的种类、种源及生成变化，具体训释有分歧。另：属于古代生成变化论的表达，不宜直接改写成现代生物学命题。"},{id:"yuyan-xiangshan",term:"相禅",pinyin:"xiāng shàn",meaning:"相互递代、接续。另：“禅”在此不是禅宗或坐禅。"},{id:"yuyan-shizu",term:"始卒",pinyin:"shǐ zú",meaning:"开始与终结。"},{id:"yuyan-ruohuan",term:"若环",pinyin:"ruò huán",meaning:"像环一样循环相接。另：强调终始相连，不宜当作已经得到科学验证的普遍循环定律。"},{id:"yuyan-lun",term:"伦",pinyin:"lún",meaning:"次序、条理、脉络。另：“莫得其伦”可联系变化过程难以穷尽来理解，不必解释为世界完全无序。"},{id:"yuyan-tianjun",term:"天均",pinyin:"tiān jūn",meaning:"自然的均平、调和，也可联系自然运转理解。另：原文以“天均者，天倪也”联系二者；自然调和不等于抹平所有差异。"}],o=[{id:"yuyan-01",label:"三言与言说·接受、识见与变化",sentences:[[{text:"寓言",glossary:"yuyan-yuyan"},{text:"十九",glossary:"yuyan-shijiu"},"，",{text:"重言",glossary:"yuyan-zhongyan"},{text:"十七",glossary:"yuyan-shiqi"},"，",{text:"卮言",glossary:"yuyan-zhiyan"},{text:"日出",glossary:"yuyan-richu"},"，",{text:"和以天倪",glossary:"yuyan-heyi-tianni"},"。"],[{text:"寓言",glossary:"yuyan-yuyan"},{text:"十九",glossary:"yuyan-shijiu"},"，",{text:"藉外论之",glossary:"yuyan-jiewai"},"。"],[{text:"亲父",glossary:"yuyan-qinfu"},"不",{text:"为其子媒",glossary:"yuyan-weizi-mei"},"。亲父",{text:"誉之",glossary:"yuyan-yuzhi"},"，不若非其父者也。"],["非吾",{text:"罪",glossary:"yuyan-zui"},"也，人之罪也。"],[{text:"与己同则应",glossary:"yuyan-tongze-ying"},"，",{text:"不与己同则反",glossary:"yuyan-butongze-fan"},"。同于己为",{text:"是之",glossary:"yuyan-shizhi-feizhi"},"，异于己为",{text:"非之",glossary:"yuyan-shizhi-feizhi"},"。"],[{text:"重言",glossary:"yuyan-zhongyan"},{text:"十七",glossary:"yuyan-shiqi"},"，",{text:"所以己言也",glossary:"yuyan-suoyi-jiyan"},"。"],["是为",{text:"耆艾",glossary:"yuyan-qiai"},"，",{text:"年先矣",glossary:"yuyan-nianxian"},"，而无",{text:"经纬",glossary:"yuyan-jingwei"},{text:"本末",glossary:"yuyan-benmo"},{text:"以期年耆",glossary:"yuyan-yiqi-nianqi"},"者，",{text:"是非先也",glossary:"yuyan-shifeixian"},"。"],["人而",{text:"无以先人",glossary:"yuyan-wuyi-xianren"},"，",{text:"无人道",glossary:"yuyan-wurendao"},"也。人而无人道，是之谓",{text:"陈人",glossary:"yuyan-chenren"},"。"],[{text:"卮言",glossary:"yuyan-zhiyan"},{text:"日出",glossary:"yuyan-richu"},"，",{text:"和以天倪",glossary:"yuyan-heyi-tianni"},"，",{text:"因以曼衍",glossary:"yuyan-manyan"},"，所以",{text:"穷年",glossary:"yuyan-qiongnian"},"。"],["不言则",{text:"齐",glossary:"yuyan-qi"},"，齐与言不齐，言与齐不齐也。"],["故曰：“",{text:"言无言",glossary:"yuyan-yanwuyan"},"。”言无言：终身言，未尝言；终身不言，未尝不言。"],[{text:"有自也",glossary:"yuyan-youzi"},"而",{text:"可",glossary:"yuyan-ke-buke"},"，有自也而",{text:"不可",glossary:"yuyan-ke-buke"},"；有自也而",{text:"然",glossary:"yuyan-ran-buran"},"，有自也而",{text:"不然",glossary:"yuyan-ran-buran"},"。"],[{text:"恶乎",glossary:"yuyan-wuhu"},"然？然于然；恶乎不然？不然于不然。恶乎可？可于可；恶乎不可？不可于不可。"],["物固",{text:"有所然",glossary:"yuyan-yousuoran-ke"},"，物固",{text:"有所可",glossary:"yuyan-yousuoran-ke"},"。无物不然，无物不可。"],["非",{text:"卮言",glossary:"yuyan-zhiyan"},{text:"日出",glossary:"yuyan-richu"},"，",{text:"和以天倪",glossary:"yuyan-heyi-tianni"},"，",{text:"孰得其久",glossary:"yuyan-shudeqijiu"},"！"],[{text:"万物皆种",glossary:"yuyan-wanwu-jiezhong"},"也，以不同形",{text:"相禅",glossary:"yuyan-xiangshan"},"，",{text:"始卒",glossary:"yuyan-shizu"},{text:"若环",glossary:"yuyan-ruohuan"},"，莫得其",{text:"伦",glossary:"yuyan-lun"},"，是谓",{text:"天均",glossary:"yuyan-tianjun"},"。"],[{text:"天均",glossary:"yuyan-tianjun"},"者，",{text:"天倪",glossary:"yuyan-tianni"},"也。"]]}],p=[{term:"寓言",pinyin:"yù yán",meaning:"寄寓之言，借外在人物、他者或情境来论说。"},{term:"重言",pinyin:"zhòng yán",meaning:"有分量的言说，通常联系借前人、长者或受尊重者之言来论说。"},{term:"卮言",pinyin:"zhī yán",meaning:"可理解为不固执于一定判断、随情境变化而展开的言说。"},{term:"藉外论之",pinyin:"jiè wài lùn zhī",meaning:"借外在人物或他者来论说；藉，借助。"},{term:"陈人",pinyin:"chén rén",meaning:"陈旧之人，可理解为徒有年岁积累而无相应通达者。"},{term:"天倪",pinyin:"tiān ní",meaning:"自然的分际、端绪或条理；倪有端、际义。"},{term:"言无言",pinyin:"yán wú yán",meaning:"可理解为言说而不执着于言说，不以言辞封闭对象。"},{term:"相禅",pinyin:"xiāng shàn",meaning:"相互递代、接续。"},{term:"天均",pinyin:"tiān jūn",meaning:"自然的均平、调和，也可联系自然运转理解。"}],h=[{text:"寓言十九，重言十七，卮言日出，和以天倪。",guide:"先总提三种言说方式：借外表达、借重分量、随情境展开。三者可以在同一段言说中相互配合。",note:"十九与十七通常按十之九、十之七理解，不能当作互斥比例相加。"},{text:"寓言十九，藉外论之。",guide:"寓言首先改变表达的位置，把意思寄托在外在人物、他者或情境中，让读者通过问答、反差与转折接近问题。",note:"人物之言不自动等于作者的最终判断。"},{text:"亲父不为其子媒。亲父誉之，不若非其父者也。",guide:"同样的称赞，因说话者与对象的关系不同，可能得到不同的接受。听者会顾虑亲情偏爱。",note:"这不是说父亲必定虚假，也不是保证外人必定公正。"},{text:"非吾罪也，人之罪也。",guide:"结合前后文，可理解为借外论说的必要性也与听者的接受方式有关：言说可能在内容得到理解之前便被拒绝。",note:"不能扩大为作者永远正确、所有不同意者都有过失。"},{text:"与己同则应，不与己同则反。同于己为是之，异于己为非之。",guide:"反省把“是否与我相同”当作判断标准的倾向。同意与反对是关系，不能代替根据。",note:"寓言能够改变面对问题的方式，却不能保证消除偏见。"},{text:"重言十七，所以己言也。",guide:"若将“己”按“已”的止息义理解，可读为借有分量的言说，减少只凭一己意见的轻率争辩。",note:"训释有分歧；借重权威不意味着讨论必须结束。"},{text:"年先矣，而无经纬本末以期年耆者，是非先也。",guide:"年龄在先不等于识见在先。值得借重的长者，应有理解条理、本末的实际能力。",note:"句法有疑义；本段既不否认经验，也不把年齿直接兑换成正确性。"},{text:"人而无以先人，无人道也。人而无人道，是之谓陈人。",guide:"在言说权威的语境中，严厉批评徒有年长资格而无相应识见、为人之道的状态。",note:"不宜引申为所有老人都保守，或没有突出成就的人便没有价值。"},{text:"卮言日出，和以天倪，因以曼衍，所以穷年。",guide:"言说不断生出，因循情境而展开，并与自然的分际相调和；其目标是持续回应，而不是反复搬用固定公式。",note:"开放不等于任意改口、回避明确回答或一味迎合。"},{text:"不言则齐，齐与言不齐，言与齐不齐也。",guide:"可从语言与齐同的张力理解：言说一旦作出，便划出分别；即使说“万物齐一”，也仍是一个可被赞同或反对的说法。",note:"这组句子解释不一，不宜据此认定沉默拥有最终正确性。"},{text:"言无言：终身言，未尝言；终身不言，未尝不言。",guide:"一种贯通上文的理解是：持续言说未必固执于言，保持沉默也未必摆脱表达与立场。发声多少不是唯一标准。",note:"这里具有多义性，不能把这一理解当作唯一逐字译文。"},{text:"有自也而可，有自也而不可；有自也而然，有自也而不然。",guide:"相反判断各有其所从，需要追问条件、关系与出发点，而不只宣布结论。",note:"各有其所从，不等于各有同样充分的根据。"},{text:"恶乎然？然于然；恶乎不然？不然于不然。恶乎可？可于可；恶乎不可？不可于不可。",guide:"把注意力引向认定过程：某物被称为然或可，与它被怎样理解、判定有关。",note:"不能由此断言外在事物完全由语言任意创造。"},{text:"物固有所然，物固有所可。无物不然，无物不可。",guide:"联系“有所”，可理解为事物都有在某种关系或角度中被理解、认可的方面，以此松动单一尺度。",note:"不是说一切事物永远正确、一切行为都可以做。"},{text:"非卮言日出，和以天倪，孰得其久！",guide:"回到卮言：面对持续变化的情境，长久相应可能依赖修正、转换与重新表达。",note:"“久”不宜径释为个人肉身长生。"},{text:"万物皆种也，以不同形相禅，始卒若环，莫得其伦。",guide:"把言说问题放入万物生成变化之中：形态递代，终始相接，完整脉络未必能够穷尽。",note:"不能直接等同于现代进化论，也不意味着所有物种可以任意互变。"},{text:"是谓天均。天均者，天倪也。",guide:"将自然的调和与自然的分际联系起来。差异仍然存在，变化仍在发生。",note:"天均与天倪不宜被强行划成互不重叠的固定概念；调和也不是取消差异。"}],u=[{id:"yyk_liushi",term:"六十化",pinyin:"liù shí huà",meaning:"六十岁而六十年间不断变化，指年年更新、不固守旧见。化不作「化为他物」解。"},{id:"yyk_shishi",term:"始时所是",pinyin:"shǐ shí suǒ shì",meaning:"起初认为对的。与「卒而非之」连读，写自我修正的过程。"},{id:"yyk_cuofei",term:"卒而非之",pinyin:"zú ér fēi zhī",meaning:"到最后又否定了它。卒为终于。"},{id:"yyk_qinzhi",term:"勤志服知",pinyin:"qín zhì fú zhī",meaning:"勤勉立志、从事于知。服有从事、服膺等训释。（另：这是惠子的解释，不是庄子的判语。）"},{id:"yyk_xiezhi",term:"谢之",pinyin:"xiè zhī",meaning:"告谢、辞谢；有解释为「孔子对此已不再申说」。（另：句读有异，不作定论。）"},{id:"yyk_shoucai",term:"受才乎大本",pinyin:"shòu cái hū dà běn",meaning:"从大本领受才质。（另：与「复灵以生」连读，句法有解释空间。）"},{id:"yyk_fuling",term:"复灵以生",pinyin:"fù líng yǐ shēng",meaning:"复归灵性以生。（另：灵具体所指有异议，不据此建立一套生命理论。）"},{id:"yyk_minglv",term:"鸣而当律",pinyin:"míng ér dāng lǜ",meaning:"发声合于音律。与「言而当法」并列，写言说合于法度。"},{id:"yyk_yanfa",term:"言而当法",pinyin:"yán ér dāng fǎ",meaning:"说话合于法度。合规矩不等于所说必然正确。"},{id:"yyk_liyi",term:"利义陈乎前",pinyin:"lì yì chén hū qián",meaning:"利与义摆在面前。陈为陈列。"},{id:"yyk_zhifu",term:"直服人之口",pinyin:"zhí fú rén zhī kǒu",meaning:"只是使人嘴上服从。直为只、仅。（另：这是全篇关键的区分——口服不等于心服。）"},{id:"yyk_wuli",term:"蘁",pinyin:"wù",meaning:"违逆。蘁通「牾」。（另：原文作「不敢蘁，立定天下之定」，与「不敢蘁立」断句不同，此处依所据本子。）"},{id:"yyk_dingtianxia",term:"定天下之定",pinyin:"dìng tiān xià zhī dìng",meaning:"使天下安定者安定下来。（另：具体所指有解释空间，不当作某种政治方案。）"},{id:"yyk_yihu",term:"已乎",pinyin:"yǐ hū",meaning:"算了吧。叠用表感叹与收束。"},{id:"yyk_budeji",term:"不得及彼",pinyin:"bù dé jí bǐ",meaning:"还赶不上他。彼指孔子。（另：这是庄子的推许，不是定评。）"}],g=[{id:"yuyan-02",label:"孔子六十化·自我修正与前见",sentences:[["庄子谓惠子曰：「孔子行年",{text:"六十化",glossary:"yyk_liushi"},"，",{text:"始时所是",glossary:"yyk_shishi"},"，",{text:"卒而非之",glossary:"yyk_cuofei"},"，未知今之所谓是之非五十九非也。」"],["惠子曰：「孔子",{text:"勤志服知",glossary:"yyk_qinzhi"},"也。」"],["庄子曰：「孔子",{text:"谢之",glossary:"yyk_xiezhi"},"矣，而其未之尝言也。孔子云：夫",{text:"受才乎大本",glossary:"yyk_shoucai"},"，",{text:"复灵以生",glossary:"yyk_fuling"},"。",{text:"鸣而当律",glossary:"yyk_minglv"},"，",{text:"言而当法",glossary:"yyk_yanfa"},"。",{text:"利义陈乎前",glossary:"yyk_liyi"},"，而好恶是非",{text:"直服人之口",glossary:"yyk_zhifu"},"而已矣。使人乃以心服而不敢",{text:"蘁",glossary:"yyk_wuli"},"，立",{text:"定天下之定",glossary:"yyk_dingtianxia"},"。",{text:"已乎",glossary:"yyk_yihu"},"，已乎！吾且",{text:"不得及彼",glossary:"yyk_budeji"},"乎！」"]]}],m=[{term:"六十化",pinyin:"liù shí huà",meaning:"六十岁而六十年间不断变化，指年年更新、不固守旧见。"},{term:"始时所是",pinyin:"shǐ shí suǒ shì",meaning:"起初认为对的；与「卒而非之」连读，写自我修正的过程。"},{term:"勤志服知",pinyin:"qín zhì fú zhī",meaning:"勤勉立志、从事于知。这是惠子的解释，不是庄子的判语。"},{term:"直服人之口",pinyin:"zhí fú rén zhī kǒu",meaning:"只是使人嘴上服从。全篇关键的区分——口服不等于心服。"},{term:"蘁",pinyin:"wù",meaning:"违逆，通「牾」。原文「不敢蘁，立定天下之定」。"},{term:"大本",pinyin:"dà běn",meaning:"大道、根本。"}],b=[{text:"孔子行年六十而六十化。",guide:"六十岁仍在改写自己的判断。化不是变成别的东西，是不断修正。",note:"不据此认定孔子本人确有此说，这是《庄子》中的孔子。"},{text:"始时所是，卒而非之。",guide:"起初认为对的，最后又否定——自我修正不是失败，而是仍在推进。"},{text:"未知今之所谓是之非五十九非也。",guide:"今天的「是」，也许正是昨天所否定的东西；判断的坐标本身在移动。",note:"不推出「一切判断都不可靠」的结论。"},{text:"孔子勤志服知也。",guide:"惠子的解释：那是勤勉与求知。换一个角度，同一种变化就有不同说法。"},{text:"孔子谢之矣，而其未之尝言。",guide:"对此不再申说。真正改过的人，往往不忙于解释自己为什么改了。",note:"句读有异，不作定论。"},{text:"鸣而当律，言而当法。",guide:"发声合于音律，说话合于法度。合规矩仍是外在的准确。"},{text:"利义陈乎前，而好恶是非直服人之口而已矣。",guide:"把利与义摆在面前，用是非好恶去说服，也只是让人嘴上服从。"},{text:"使人乃以心服而不敢蘁，立定天下之定。",guide:"要的是心服，而不是不敢违逆。二者差别极大。",note:"断句依所据本子，与「不敢蘁立」分读不同。"},{text:"已乎！已乎！吾且不得及彼乎！",guide:"庄子的叹服：这样的境界，我恐怕还赶不上。"}],x=[{id:"yyz_zaishi",term:"再仕",pinyin:"zài shì",meaning:"两次出仕。再为第二次。"},{id:"yyz_xinhuo",term:"心再化",pinyin:"xīn zài huà",meaning:"心境再次变化。与前则「六十化」的化字相呼应。"},{id:"yyz_jueqin",term:"及亲仕",pinyin:"jí qīn shì",meaning:"在父母在世时出仕。及为赶上、趁着。"},{id:"yyz_sanfu",term:"三釜",pinyin:"sān fǔ",meaning:"微薄俸禄。釜为量器，三釜言其少。"},{id:"yyz_buji",term:"不洎",pinyin:"bù jì",meaning:"不能及于亲。洎为及。（另：有解释为「不洎乎亲」，指亲已不在。）"},{id:"yyz_wusuoxian",term:"无所县其罪",pinyin:"wú suǒ xuán qí zuì",meaning:"县通「悬」，牵挂、系累；罪有解释为「累」。句意为「是否已没有所牵挂的过失」。（另：句法与「罪」的训释有异，不作定论。）"},{id:"yyz_jixian",term:"既已县矣",pinyin:"jì yǐ xuán yǐ",meaning:"已经有所系累了。孔子的回答：并非无所牵挂。"},{id:"yyz_youai",term:"可以有哀乎",pinyin:"kě yǐ yǒu āi hū",meaning:"还可能哀伤吗。以反问指出：真无所系者，不会仍被俸禄与亲情牵动。"},{id:"yyz_quewenmeng",term:"雀蚊虻",pinyin:"què wén méng",meaning:"雀与蚊虻，喻细小之物，一掠而过。"},{id:"yyz_sanjin",term:"三千锺",pinyin:"sān qiān zhōng",meaning:"极厚的俸禄。锺为容量单位。（另：与前文「三釜」对举，一薄一厚。）"}],c=[{id:"yuyan-03",label:"曾子再仕·俸禄与养亲",sentences:[["曾子",{text:"再仕",glossary:"yyz_zaishi"},"而",{text:"心再化",glossary:"yyz_xinhuo"},"，曰：「吾",{text:"及亲仕",glossary:"yyz_jueqin"},"，",{text:"三釜",glossary:"yyz_sanfu"},"而心乐；后仕，三千锺而",{text:"不洎",glossary:"yyz_buji"},"，吾心悲。」"],["弟子问于仲尼曰：「若参者，可谓",{text:"无所县其罪",glossary:"yyz_wusuoxian"},"乎？」"],["曰：「",{text:"既已县矣",glossary:"yyz_jixian"},"！夫无所县者，",{text:"可以有哀乎",glossary:"yyz_youai"},"？彼视三釜、",{text:"三千锺",glossary:"yyz_sanjin"},"，如观",{text:"雀蚊虻",glossary:"yyz_quewenmeng"},"相过乎前也。」"]]}],q=[{term:"再仕",pinyin:"zài shì",meaning:"两次出仕。"},{term:"心再化",pinyin:"xīn zài huà",meaning:"心境再次变化，与前则「六十化」的化字呼应。"},{term:"三釜",pinyin:"sān fǔ",meaning:"微薄俸禄；与后文「三千钟」对举。"},{term:"不洎",pinyin:"bù jì",meaning:"不能及于亲。洎为及。"},{term:"无所县",pinyin:"wú suǒ xuán",meaning:"县通「悬」，无所牵挂。"},{term:"及亲仕",pinyin:"jí qīn shì",meaning:"在父母在世时出仕；乐与悲不在俸禄多少，在能不能及。"}],k=[{text:"曾子再仕而心再化。",guide:"俸禄变了，心也跟着变——这是全则的实情，不是要掩饰的过失。"},{text:"吾及亲仕，三釜而心乐。",guide:"俸禄很薄，却乐：因为还能养亲。"},{text:"后仕，三千钟而不洎，吾心悲。",guide:"俸禄极厚，却悲：因为亲已不在。乐与悲不在数目，在能不能及。"},{text:"若参者，可谓无所县其罪乎？",guide:"弟子在问：这样算是已经不被牵累了吗？",note:"「县」「罪」的训释有异，此处只取大意。"},{text:"既已县矣。",guide:"孔子的回答很干脆：仍然有所系。"},{text:"夫无所县者，可以有哀乎？",guide:"真正无所系累的人，还会被俸禄与往事牵动吗？"},{text:"彼视三釜、三千锺，如观雀蚊虻相过乎前也。",guide:"在那种人眼里，薄禄厚禄都只是眼前一掠而过的飞虫。"}],_=[{id:"yyy_ye",term:"野",pinyin:"yě",meaning:"质朴、不文饰。九年的第一层，先去掉浮华。"},{id:"yyy_cong",term:"从",pinyin:"cóng",meaning:"随顺，不硬顶。"},{id:"yyy_tong",term:"通",pinyin:"tōng",meaning:"通达，滞碍减少。"},{id:"yyy_wu",term:"物",pinyin:"wù",meaning:"与物同化、不执己见。（另：训释有异，不作定论。）"},{id:"yyy_lai",term:"来",pinyin:"lái",meaning:"有解释为「众来归之」。"},{id:"yyy_guiru",term:"鬼入",pinyin:"guǐ rù",meaning:"有解释为「鬼神来入」，形容深入幽微。（另：语涉神异，宜存疑。）"},{id:"yyy_tiancheng",term:"天成",pinyin:"tiān chéng",meaning:"自然天成，不假造作。"},{id:"yyy_damiao",term:"大妙",pinyin:"dà miào",meaning:"九年所列的最后一层，形容深微难名的境地。"},{id:"yyy_shengyou",term:"生有为，死也",pinyin:"shēng yǒu wéi, sǐ yě",meaning:"句读与解释有分歧：或解为「生而有为，即是死路」，或另作断句。（另：此句不宜当成定论式命题。）"},{id:"yyy_quangong",term:"劝公",pinyin:"quàn gōng",meaning:"「劝公以其私」句法难解，有解释为「劝而公之」。（另：私字与他本或作「和」，存疑。）"},{id:"yyy_youzi2",term:"有自也",pinyin:"yǒu zì yě",meaning:"有所从出、有来由。与「无自也」对举。"},{id:"yyy_shengyang",term:"生阳也",pinyin:"shēng yáng yě",meaning:"有解释为生而属阳。（另：阴阳在此非固定实体。）"},{id:"yyy_lishu",term:"历数",pinyin:"lì shù",meaning:"天象历数、岁时次第。"},{id:"yyy_renju",term:"人据",pinyin:"rén jù",meaning:"人所依据。（另：解释有异，或指人迹所据之地。）"},{id:"yyy_wuming",term:"无命",pinyin:"wú mìng",meaning:"没有命定。与「有命」对举，两端都被提问。"},{id:"yyy_wugui",term:"无鬼",pinyin:"wú guǐ",meaning:"没有鬼。与「有鬼」对举，同样只是发问。"}],f=[{id:"yuyan-04",label:"颜成子游·九年之序与两端之问",sentences:[["颜成子游谓东郭子綦曰：「自吾闻子之言，一年而",{text:"野",glossary:"yyy_ye"},"，二年而",{text:"从",glossary:"yyy_cong"},"，三年而",{text:"通",glossary:"yyy_tong"},"，四年而",{text:"物",glossary:"yyy_wu"},"，五年而",{text:"来",glossary:"yyy_lai"},"，六年而",{text:"鬼入",glossary:"yyy_guiru"},"，七年而",{text:"天成",glossary:"yyy_tiancheng"},"，八年而不知死、不知生，九年而",{text:"大妙",glossary:"yyy_damiao"},"。"],[{text:"生有为，死也",glossary:"yyy_shengyou"},"。",{text:"劝公",glossary:"yyy_quangong"},"以其私，死也",{text:"有自也",glossary:"yyy_youzi2"},"，而",{text:"生阳也",glossary:"yyy_shengyang"},"，无自也。而果然乎？恶乎其所适？恶乎其所不适？天有",{text:"历数",glossary:"yyy_lishu"},"，地有",{text:"人据",glossary:"yyy_renju"},"，吾恶乎求之？莫知其所终，若之何其",{text:"无命",glossary:"yyy_wuming"},"也？莫知其所始，若之何其有命也？有以相应也，若之何其",{text:"无鬼",glossary:"yyy_wugui"},"邪？无以相应也，若之何其有鬼邪？」"]]}],z=[{term:"一年而野",pinyin:"yī nián ér yě",meaning:"第一年先回到质朴，去掉浮华。"},{term:"鬼入",pinyin:"guǐ rù",meaning:"有解释为「鬼神来入」，形容深入幽微；语涉神异，宜存疑。"},{term:"天成",pinyin:"tiān chéng",meaning:"自然天成，不假造作。"},{term:"大妙",pinyin:"dà miào",meaning:"九年所列的最后一层，形容深微难名的境地。"},{term:"历数",pinyin:"lì shù",meaning:"天象历数、岁时次第。"},{term:"人据",pinyin:"rén jù",meaning:"人所依据；解释有异。"}],P=[{text:"自吾闻子之言，一年而野。",guide:"修学的第一步不是加，而是减——先回到质朴。"},{text:"三年而通，四年而物。",guide:"通畅之后不执己见，能与物相处。"},{text:"六年而鬼入，七年而天成。",guide:"越往后越难用常语描述，只能列名。",note:"「鬼入」的具体所指有异说，不据以谈神异。"},{text:"八年而不知死、不知生。",guide:"死生之辨在这里淡下去，不是获得长生。"},{text:"九年而大妙。",guide:"九年是一个次序，也是一种说法——不必当作人人都要走的年限。"},{text:"生有为，死也。",guide:"句读与解释都有分歧，此处只提示它的问题意识：有为与生死的牵连。",note:"不宜当成定论式命题，更不用于归责病人。"},{text:"莫知其所终，若之何其无命也？莫知其所始，若之何其有命也？",guide:"不知其终，能说没有命定吗？不知其始，能说有命定吗？两端都不肯替我们作证。"},{text:"有以相应也，若之何其无鬼邪？无以相应也，若之何其有鬼邪？",guide:"同样的句式用于鬼：有相应则难以说无，无相应则难以说有——留下的是疑问，不是结论。"}],w=[{id:"yys_wangliang",term:"罔两",pinyin:"wǎng liǎng",meaning:"影外的微阴、影子的边缘。（另：或解为「影子的影子」，解释有异，不据此立论。）"},{id:"yys_jing",term:"景",pinyin:"jǐng",meaning:"影子。古「景」通「影」。"},{id:"yys_xiangye",term:"向也",pinyin:"xiàng yě",meaning:"刚才、先前。与「今也」对举。"},{id:"yys_kuo",term:"括撮",pinyin:"kuò cuō",meaning:"束发、束结。与「被发」相对。"},{id:"yys_pifa",term:"被发",pinyin:"pī fà",meaning:"披散头发。被通「披」。"},{id:"yys_sousou",term:"搜搜",pinyin:"sōu sōu",meaning:"形容动而不定；或解为「区区」之意。（另：训释有异，存疑。）"},{id:"yys_xishao",term:"奚稍问",pinyin:"xī shāo wèn",meaning:"何必急急发问。稍为急、渐之意。（另：句读有异。）"},{id:"yys_tiaoji",term:"蜩甲",pinyin:"tiáo jiǎ",meaning:"蝉蜕。蝉所脱的壳，形似而非本体。"},{id:"yys_shetui",term:"蛇蜕",pinyin:"shé tuì",meaning:"蛇所脱的皮。与蜩甲并列，取「似之而非」。"},{id:"yys_tun",term:"屯",pinyin:"tún",meaning:"聚集、停留。火与日下影子聚而显。"},{id:"yys_dai",term:"代",pinyin:"dài",meaning:"替、代谢。阴与夜则影子隐去。"},{id:"yys_youDai",term:"有待",pinyin:"yǒu dài",meaning:"有所依赖、有所待。影待形与光，形又有所待。"},{id:"yys_qiangyang",term:"强阳",pinyin:"qiáng yáng",meaning:"运动、有力之状。（另：或解为「相随而动」，训释有异。）"}],j=[{id:"yuyan-05",label:"众罔两问景·所待与随动",sentences:[["众",{text:"罔两",glossary:"yys_wangliang"},"问于",{text:"景",glossary:"yys_jing"},"曰：「若",{text:"向也",glossary:"yys_xiangye"},"俯而今也仰，向也",{text:"括撮",glossary:"yys_kuo"},"而今也",{text:"被发",glossary:"yys_pifa"},"，向也坐而今也起，向也行而今也止，何也？」"],["景曰：「",{text:"搜搜",glossary:"yys_sousou"},"也，",{text:"奚稍问",glossary:"yys_xishao"},"也！予有而不知其所以。予，",{text:"蜩甲",glossary:"yys_tiaoji"},"也，",{text:"蛇蜕",glossary:"yys_shetui"},"也，似之而非也。火与日，吾",{text:"屯",glossary:"yys_tun"},"也；阴与夜，吾",{text:"代",glossary:"yys_dai"},"也。彼，吾所以",{text:"有待",glossary:"yys_youDai"},"邪，而况乎以无有待者乎！彼来则我与之来，彼往则我与之往，彼",{text:"强阳",glossary:"yys_qiangyang"},"则我与之强阳。强阳者，又何以有问乎！」"]]}],T=[{term:"罔两",pinyin:"wǎng liǎng",meaning:"影外的微阴、影子的边缘；或解为「影子的影子」，解释有异。"},{term:"蜩甲",pinyin:"tiáo jiǎ",meaning:"蝉蜕——形似而非本体。"},{term:"蛇蜕",pinyin:"shé tuì",meaning:"蛇所脱的皮；与蜩甲并列，取「似之而非」。"},{term:"有待",pinyin:"yǒu dài",meaning:"有所依赖、有所待。影待形与光，形又有所待。"},{term:"强阳",pinyin:"qiáng yáng",meaning:"运动、有力之状；训释有异。"},{term:"奚稍问",pinyin:"xī shāo wèn",meaning:"何必急急发问。"}],S=[{text:"若向也俯而今也仰，向也括撮而今也被发；向也坐而今也起；向也行而今也止：何也？",guide:"一连四个对照：影子的动作全在变。问的是「为什么」。"},{text:"予有而不知其所以。",guide:"影子承认：我有这些变化，却不知道其中缘故。"},{text:"予，蜩甲也，蛇蜕也，似之而非也。",guide:"像蝉蜕、像蛇皮——形状还在，本体已去。影与形的关系正是如此。"},{text:"火与日，吾屯也；阴与夜，吾代也。",guide:"有光则聚而显，无光则隐而去。"},{text:"彼，吾所以有待邪，而况乎以无有待者乎！",guide:"我有所待；何况那个并不有待的东西？一句把追问推上一层。",note:"「无有待」依所据本子，他本或作「以有待者」。"},{text:"彼来则我与之来，彼往则我与之往。",guide:"随动而动，不自主，也无须自主。"},{text:"强阳者，又何以有问乎！",guide:"一切都在动，又何必问谁在动。",note:"这里不是取消因果，而是承认自己站在链条的中段。"}],C=[{id:"yyr_yangziju",term:"阳子居",pinyin:"yáng zǐ jū",meaning:"人名，一说即杨朱。（另：其人其名有异说，不据本段定其学派。）"},{id:"yyr_nanzhipei",term:"南之沛",pinyin:"nán zhī pèi",meaning:"往南到沛。之为往。"},{id:"yyr_yaoyujiao",term:"邀于郊",pinyin:"yāo yú jiāo",meaning:"在郊外相约等候。邀为邀约、等候。"},{id:"yyr_zhongdao",term:"中道",pinyin:"zhōng dào",meaning:"半路。"},{id:"yyr_guanshu",term:"盥漱巾栉",pinyin:"guàn shù jīn zhì",meaning:"洗脸漱口之具与毛巾梳篦。写弟子服事之礼。"},{id:"yyr_tuoju",term:"脱屦户外",pinyin:"tuō jù hù wài",meaning:"在门外脱鞋。屦为鞋。"},{id:"yyr_xixing",term:"膝行",pinyin:"xī xíng",meaning:"跪行，表恭敬。"},{id:"yyr_suisui",term:"睢睢盱盱",pinyin:"suī suī xū xū",meaning:"形容直视、傲视之状。（另：解释有异，或解为跋扈自得。）"},{id:"yyr_dabai",term:"大白若辱",pinyin:"dà bái ruò rǔ",meaning:"最白好像含垢。语见《老子》。"},{id:"yyr_shengde",term:"盛德若不足",pinyin:"shèng dé ruò bù zú",meaning:"德盛而自处如不足。与「大白若辱」并列，都是反显之辞。"},{id:"yyr_curan",term:"蹴然",pinyin:"cù rán",meaning:"惊惭不安之状。"},{id:"yyr_shezhe",term:"舍者",pinyin:"shè zhě",meaning:"旅舍中的人，包括同舍旅客与执事者。"},{id:"yyr_zhixi",term:"执席",pinyin:"zhí xí",meaning:"持席侍奉。写众人格外恭敬。"},{id:"yyr_bixi",term:"避席",pinyin:"bì xí",meaning:"离席让位。"},{id:"yyr_yangzhe",term:"炀者",pinyin:"yáng zhě",meaning:"炊火者。"},{id:"yyr_zhengxi",term:"争席",pinyin:"zhēng xí",meaning:"争座位。形容不再被当作特殊人物对待——这是关系变近，不是受辱。"}],A=[{id:"yuyan-06",label:"阳子居见老聃·神态与争席",sentences:[["",{text:"阳子居",glossary:"yyr_yangziju"},{text:"南之沛",glossary:"yyr_nanzhipei"},"，老聃西游于秦。",{text:"邀于郊",glossary:"yyr_yaoyujiao"},"，至于梁而遇老子。"],["老子",{text:"中道",glossary:"yyr_zhongdao"},"仰天而叹曰：「始以汝为可教，今不可也。」"],["阳子居不答。"],["至舍，进",{text:"盥漱巾栉",glossary:"yyr_guanshu"},"，",{text:"脱屦户外",glossary:"yyr_tuoju"},"，",{text:"膝行",glossary:"yyr_xixing"},"而前，曰：「向者弟子欲请夫子，夫子行不闲，是以不敢；今闲矣，请问其故。」"],["老子曰：「而",{text:"睢睢盱盱",glossary:"yyr_suisui"},"，而谁与居！",{text:"大白若辱",glossary:"yyr_dabai"},"，",{text:"盛德若不足",glossary:"yyr_shengde"},"。」"],["阳子居",{text:"蹴然",glossary:"yyr_curan"},"变容曰：「敬闻命矣！」"],["其往也，",{text:"舍者",glossary:"yyr_shezhe"},"迎将其家，公",{text:"执席",glossary:"yyr_zhixi"},"，妻",{text:"盥漱巾栉",glossary:"yyr_guanshu"},"，舍者",{text:"避席",glossary:"yyr_bixi"},"，",{text:"炀者",glossary:"yyr_yangzhe"},"避灶。"],["其反也，舍者与之",{text:"争席",glossary:"yyr_zhengxi"},"矣！"]]}],D=[{term:"阳子居",pinyin:"yáng zǐ jū",meaning:"人名，一说即杨朱；其人其名有异说。"},{term:"盥漱巾栉",pinyin:"guàn shù jīn zhì",meaning:"洗脸漱口之具与毛巾梳篦，写弟子服事之礼。"},{term:"睢睢盱盱",pinyin:"suī suī xū xū",meaning:"形容直视、傲视之状；解释有异。"},{term:"大白若辱",pinyin:"dà bái ruò rǔ",meaning:"最白好像含垢。语见《老子》。"},{term:"蹴然",pinyin:"cù rán",meaning:"惊惭不安之状。"},{term:"争席",pinyin:"zhēng xí",meaning:"争座位。不再被当特殊人物对待，是关系变近，不是受辱。"}],V=[{text:"阳子居南之沛，老聃西游于秦。邀于郊，至于梁而遇老子。",guide:"一次偶遇，也是一场没有预告的考试。"},{text:"始以汝为可教，今不可也。",guide:"老子的第一句就是否定，且不解释理由。"},{text:"阳子居不答。",guide:"被否定而不辩解——这一处沉默比任何反驳都重要。"},{text:"至舍，进盥漱巾栉，脱屦户外，膝行而前。",guide:"不是赌气走开，而是执礼再问。"},{text:"向者弟子欲请夫子，夫子行不闲，是以不敢；今闲矣，请问其故。",guide:"问的是「故」（缘故），不是急着自辩。",note:"他本或作「请问其过」，此依所据本子。"},{text:"而睢睢盱盱，而谁与居！",guide:"那副眼神与姿态，谁愿意和你相处？问题不在道理，在气息。"},{text:"大白若辱，盛德若不足。",guide:"最白的好似含垢，最盛的德好似不足——所以不必把「我很行」写在脸上。"},{text:"其往也，舍者迎将其家，公执席，妻执巾栉，舍者避席，炀者避灶。",guide:"初来时，人人让位、处处侍奉。那种恭敬，往往是距离。"},{text:"其反也，舍者与之争席矣！",guide:"回来时，人们敢和他争座位了——他终于被当成一个普通可亲近的人。",note:"争席是关系变近的记号，不是失了体面。"}];return(E,t)=>{const v=l("DaoReadingPrelude"),e=l("DaoTextReading"),d=l("DaoKeywordCards"),r=l("DaoLineGuide");return K(),N("div",null,[t[0]||(t[0]=a("h1",{id:"庄子·寓言",tabindex:"-1"},[n("庄子·寓言 "),a("a",{class:"header-anchor",href:"#庄子·寓言","aria-label":'Permalink to "庄子·寓言"'},"​")],-1)),i(v,{title:"先读六则：话怎样说、人怎样改、关系怎样靠近",summary:"《寓言》开篇讨论的不只是如何讲故事，而是言说怎样被听见、凭什么值得相信，以及如何避免已经成立的说法重新凝固成执著；其后五则以孔子、曾子、颜成子游、罔两问景与阳子居递相发明。",points:[{label:"接受",text:"听者是否先按说话者的身份、亲疏与意见同异作出反应？"},{label:"识见",text:"有分量的言说，是否具有超出名号与年齿的实际根据？"},{label:"开放",text:"面对不断变化的情境，判断与表达能否继续接受修正？"}],hint:"三言不是三个互不相通的分类：借外论说、借重识见与不固执的表达，可以出现在同一段言说之中；后五则把这一层落到自我修正、俸禄之悲、两端之问、所待之影与争席之交。"}),t[1]||(t[1]=a("h2",{id:"一、三言与言说·接受、识见与变化",tabindex:"-1"},[n("一、三言与言说·接受、识见与变化 "),a("a",{class:"header-anchor",href:"#一、三言与言说·接受、识见与变化","aria-label":'Permalink to "一、三言与言说·接受、识见与变化"'},"​")],-1)),t[2]||(t[2]=a("h3",{id:"原文",tabindex:"-1"},[n("原文 "),a("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),i(e,{sections:o,glossary:y,"default-mode":"classic","aria-label":"寓言·三言与言说 原文"}),t[3]||(t[3]=a("h3",{id:"字词释义",tabindex:"-1"},[n("字词释义 "),a("a",{class:"header-anchor",href:"#字词释义","aria-label":'Permalink to "字词释义"'},"​")],-1)),i(d,{items:p}),t[4]||(t[4]=a("blockquote",null,[a("p",null,[a("strong",null,"阅读说明")]),a("p",null,"原文依所提供文本录入，标点亦保留其基本形式。“所以己言也”“以期年耆”“不言则齐”“万物皆种”等处存在训释或句法疑义。以下解释用于帮助贯通语境，不将其中一种理解强定为唯一答案。"),a("p",null,"原文、字词解释与引申解读分开呈现；现代例子和阅读提醒不视为原文逐项列出的规则。")],-1)),t[5]||(t[5]=a("h3",{id:"逐句导读",tabindex:"-1"},[n("逐句导读 "),a("a",{class:"header-anchor",href:"#逐句导读","aria-label":'Permalink to "逐句导读"'},"​")],-1)),i(r,{lines:h}),t[6]||(t[6]=s('<h3 id="深入解读" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、三言总提-三种方式-不是三只互不相通的盒子" tabindex="-1">一、三言总提：三种方式，不是三只互不相通的盒子 <a class="header-anchor" href="#一、三言总提-三种方式-不是三只互不相通的盒子" aria-label="Permalink to &quot;一、三言总提：三种方式，不是三只互不相通的盒子&quot;">​</a></h4><blockquote><p>寓言十九，重言十七，卮言日出，和以天倪。</p></blockquote><p>篇首先提出三种言说方式，随后分别展开。</p><table tabindex="0"><thead><tr><th>言说方式</th><th>可以先把握的特点</th><th>主要着眼点</th></tr></thead><tbody><tr><td>寓言</td><td>借外论说</td><td>改变表达的位置</td></tr><tr><td>重言</td><td>借有分量的言说</td><td>增加被认真听取的可能</td></tr><tr><td>卮言</td><td>不固执于一定判断，与变化相应</td><td>避免言说凝固成执著</td></tr></tbody></table><p>三者不是互相排斥的分类。一段借孔子之口展开的对话，可能同时具有几种性质：</p><ul><li>因为借人物论说而具有<strong>寓言</strong>性质；</li><li>因为人物受到尊重而具有<strong>重言</strong>性质；</li><li>因为言说随情境转折、不固执于单一判断而表现出<strong>卮言</strong>的特点。</li></ul><p>因而，“十九”与“十七”不能相加成互斥的百分比，也不宜据此统计全书篇幅。</p><p>这一开篇首先关心的是：<strong>言说如何发生作用，以及怎样避免言说成为新的执著。</strong></p><h4 id="二、藉外论之-寓言首先改变的是-谁在说" tabindex="-1">二、藉外论之：寓言首先改变的是“谁在说” <a class="header-anchor" href="#二、藉外论之-寓言首先改变的是-谁在说" aria-label="Permalink to &quot;二、藉外论之：寓言首先改变的是“谁在说”&quot;">​</a></h4><blockquote><p>寓言十九，藉外论之。</p></blockquote><p>“寓”有寄托、寄寓的意味。这里对寓言的说明，不是每个故事最后都要附上一条教训，而是把所要论说的意思寄托在外在人物、他者或情境之中。</p><p>因此，寓言可以表现为：</p><ul><li>人物之间的问答；</li><li>动物、影子等非人事物的言说；</li><li>对历史人物的重新安排；</li><li>具有反差与转折的生活故事。</li></ul><p>这些形式使表达者不必始终以“我认为”正面立论。读者先进入情境，再从人物的冲突、反应与转折中领会问题。</p><p>但“藉外”只是改变表达的位置，<strong>不等于作者完全没有立场，也不意味着人物的每一句话都代表作者的最终判断</strong>。理解寓言，需要看整个情境怎样展开，而不能只摘取其中一句作为结论。</p><h4 id="三、亲父不为其子媒-同一句称赞-换个人说便不同" tabindex="-1">三、亲父不为其子媒：同一句称赞，换个人说便不同 <a class="header-anchor" href="#三、亲父不为其子媒-同一句称赞-换个人说便不同" aria-label="Permalink to &quot;三、亲父不为其子媒：同一句称赞，换个人说便不同&quot;">​</a></h4><blockquote><p>亲父不为其子媒。亲父誉之，不若非其父者也。</p></blockquote><p>父亲称赞自己的儿子，听者容易怀疑其中有亲情偏爱。同样的话，若由不是父亲的人说，往往更容易被接受。</p><table tabindex="0"><thead><tr><th>说话者</th><th>听者可能产生的反应</th></tr></thead><tbody><tr><td>亲生父亲</td><td>你是不是偏爱自己的儿子？</td></tr><tr><td>非亲属者</td><td>你的评价似乎更有独立性。</td></tr></tbody></table><p>这里的“似乎”很重要：非亲属者也可能偏袒，父亲也可能判断准确。</p><p>原文关注的是<strong>接受上的差异</strong>，不是保证外人的话一定更真实，也不是确立一条普遍适用的婚姻规定。</p><p>它揭示的是：听者判断一句话，不只看内容，也会看说话者与所说对象的关系。</p><h4 id="四、非吾罪也-人之罪也-借外论说也与听者有关" tabindex="-1">四、非吾罪也，人之罪也：借外论说也与听者有关 <a class="header-anchor" href="#四、非吾罪也-人之罪也-借外论说也与听者有关" aria-label="Permalink to &quot;四、非吾罪也，人之罪也：借外论说也与听者有关&quot;">​</a></h4><blockquote><p>非吾罪也，人之罪也。</p></blockquote><p>这句紧接父亲作媒的比喻，随后又转入听者对同异意见的反应。结合这一语境，可以理解为：借外论说的必要性，不只是表达者的问题，也与人们听话的方式有关。</p><p>人可能因为怀疑说话者有私心、不喜欢说话者，或不愿接受与自己不同的意见，而在认真理解内容之前便作出判断。</p><p>“罪”在这里指过失、问题所在，不是现代法律意义上的犯罪。</p><p>但这句话不宜扩大为：</p><ul><li>作者的一切表达都正确；</li><li>凡不同意作者的人都错了；</li><li>言说者不需要再检验自己的根据。</li></ul><p>它揭露的是言说面对的接受障碍，<strong>不是给言说者一张永远正确的许可证</strong>。</p><h4 id="五、与己同则应-听者可能先守住自己-再判断内容" tabindex="-1">五、与己同则应：听者可能先守住自己，再判断内容 <a class="header-anchor" href="#五、与己同则应-听者可能先守住自己-再判断内容" aria-label="Permalink to &quot;五、与己同则应：听者可能先守住自己，再判断内容&quot;">​</a></h4><blockquote><p>与己同则应，不与己同则反。同于己为是之，异于己为非之。</p></blockquote><p>两组句子反复指出同一种倾向：</p><ul><li>与自己一致，便赞同；</li><li>与自己不同，便反对；</li><li>相同，被认作正确；</li><li>不同，被认作错误。</li></ul><p>问题在于，“是否与我相同”取代了“是否有充分根据”。</p><p>这使言说陷入困境：说得清楚，不一定能被听见；论据充分，也可能先被立场挡住。</p><p>寓言的作用之一，是暂时改变听者面对问题的方式。当读者先听一条鱼、一位隐者或一个影子的故事时，未必立即意识到自己的立场正在受到挑战。</p><p>不过，这只是对寓言可能发挥作用的机制的说明。<strong>寓言不能保证消除偏见，也不能代替对内容的检验。</strong></p><h4 id="六、重言十七-有分量的话-也要检验分量的根据" tabindex="-1">六、重言十七：有分量的话，也要检验分量的根据 <a class="header-anchor" href="#六、重言十七-有分量的话-也要检验分量的根据" aria-label="Permalink to &quot;六、重言十七：有分量的话，也要检验分量的根据&quot;">​</a></h4><blockquote><p>重言十七，所以己言也。</p></blockquote><p>“重言”通常联系借前人、长者或受尊重者之言来论说。</p><p>与寓言相比，寓言重在借外改变表达位置，重言重在言说具有某种可被重视的分量。两者可以重合，却不完全相同。</p><p>“己”若按“已”理解，便有止息之意。由此可暂理解为：借有分量的言说，使人不再只凭一己意见轻率争辩。</p><p>这一训释有分歧，不宜强定。但原文随后立即检验“有分量”的根据，因此不能把重言理解为：</p><blockquote><p>搬出一位名人，讨论便必须结束。</p></blockquote><p>真正重要的，是被借重的言说是否具有实际识见，而不只是它出自谁。</p><h4 id="七、年先矣-而非先也-年长与识见在先-不是一回事" tabindex="-1">七、年先矣，而非先也：年长与识见在先，不是一回事 <a class="header-anchor" href="#七、年先矣-而非先也-年长与识见在先-不是一回事" aria-label="Permalink to &quot;七、年先矣，而非先也：年长与识见在先，不是一回事&quot;">​</a></h4><blockquote><p>是为耆艾，年先矣，而无经纬本末以期年耆者，是非先也。</p></blockquote><p>长者确实在年龄上先于别人。但若缺乏贯通事物条理、根本与枝末的识见，就不能仅凭年齿被认定为真正的先达。</p><table tabindex="0"><thead><tr><th>在先的类型</th><th>根据</th></tr></thead><tbody><tr><td>年龄在先</td><td>活得更久、出生更早</td></tr><tr><td>识见在先</td><td>能理解条理、本末，具有可供借鉴的认识</td></tr></tbody></table><p>“以期年耆”一句句法有疑义，以上是联系上下文的一种理解，不是无争议的逐字定译。</p><p>原文不必被理解为否认经验的价值，而是在拒绝把年龄直接兑换成正确性。</p><p>活得久，可能积累经验，也可能只是重复旧有判断。是否值得借重，还需要看经验有没有转化为通达的识见。</p><h4 id="八、经纬本末-有分量-不只是记得多、资格老" tabindex="-1">八、经纬本末：有分量，不只是记得多、资格老 <a class="header-anchor" href="#八、经纬本末-有分量-不只是记得多、资格老" aria-label="Permalink to &quot;八、经纬本末：有分量，不只是记得多、资格老&quot;">​</a></h4><p>“经纬本末”可以帮助说明本段认可怎样的识见：</p><ul><li><strong>经纬</strong>：能看见事物之间的条理与关系；</li><li><strong>本末</strong>：能辨别根本与枝节，不把局部当作全部。</li></ul><p>一个人的分量，不只来自记得多少古语、经历多少年份或拥有多高名望，还在于能否使经验形成有条理的理解，并回应眼前的问题。</p><p>这也使重言与卮言不必相互冲突：有分量的识见，不一定是固定不变的公式，也可以包含对情境变化的敏感。</p><h4 id="九、陈人-批评徒具资格-不是否定所有老人" tabindex="-1">九、陈人：批评徒具资格，不是否定所有老人 <a class="header-anchor" href="#九、陈人-批评徒具资格-不是否定所有老人" aria-label="Permalink to &quot;九、陈人：批评徒具资格，不是否定所有老人&quot;">​</a></h4><blockquote><p>人而无以先人，无人道也。人而无人道，是之谓陈人。</p></blockquote><p>这几句语气严厉。结合前文关于长者和重言的讨论，可以将批评重点理解为：徒有年长资格，却缺乏相应识见与为人之道。</p><p>“陈人”突出的是积久而未通，而不是年老本身。</p><p>因而，不宜由此推出：</p><ul><li>所有老人都保守；</li><li>每个人都必须胜过别人；</li><li>没有突出成就的人便没有价值。</li></ul><p>本段讨论的是<strong>言说权威的根据</strong>，不是对所有人的生命价值进行排名。如果以先达自居，就不能只拿年龄与身份作凭据。</p><h4 id="十、从寓言到重言-既不盲从自己-也不盲从他人" tabindex="-1">十、从寓言到重言：既不盲从自己，也不盲从他人 <a class="header-anchor" href="#十、从寓言到重言-既不盲从自己-也不盲从他人" aria-label="Permalink to &quot;十、从寓言到重言：既不盲从自己，也不盲从他人&quot;">​</a></h4><p>寓言的论述主要反省听者：与我相同，不代表必然正确。</p><p>重言的论述进一步检验言者：比我年长，不代表必然高明。</p><table tabindex="0"><thead><tr><th>容易出现的判断</th><th>本段提出的校正</th></tr></thead><tbody><tr><td>他同意我，所以他说得对</td><td>同意只是关系，不是充分根据</td></tr><tr><td>他反对我，所以他说得错</td><td>差异不能代替内容检验</td></tr><tr><td>他年长、有名，所以必定正确</td><td>名号与年齿需要实际识见支撑</td></tr><tr><td>他借别人说话，所以一定在回避</td><td>借外可能是在回应接受上的困难</td></tr></tbody></table><p>寓言与重言都可以帮助言说被听见；但“被听见”“被相信”，不等于已经得到最终真理。</p><p>由此，问题进一步转向：<strong>即使一句话已经被接受，怎样避免它变成新的固执？</strong></p><h4 id="十一、卮言日出-不是一套永远不变的现成话" tabindex="-1">十一、卮言日出：不是一套永远不变的现成话 <a class="header-anchor" href="#十一、卮言日出-不是一套永远不变的现成话" aria-label="Permalink to &quot;十一、卮言日出：不是一套永远不变的现成话&quot;">​</a></h4><blockquote><p>卮言日出，和以天倪，因以曼衍，所以穷年。</p></blockquote><p>“日出”强调不断生出，“因”强调有所顺应，“曼衍”强调展开。三者合起来，表现的不是反复搬用同一条公式，而是言说随着具体情境展开，不把先前的说法变成不可改变的模板。</p><p>卮言常借酒器倾满变化的意象来解释：随变化而动，不固守一个位置。这一比喻有助于理解，却不能代替对文字与语境的考察。</p><p>卮言不宜简化为：</p><ul><li>想说什么就说什么；</li><li>永远不作明确回答；</li><li>为迎合他人而不断改口。</li></ul><p>它松动的是固执，<strong>不是取消对情境与内容的认真回应</strong>。</p><h4 id="十二、和以天倪-不强行抹平-也不固守人为分别" tabindex="-1">十二、和以天倪：不强行抹平，也不固守人为分别 <a class="header-anchor" href="#十二、和以天倪-不强行抹平-也不固守人为分别" aria-label="Permalink to &quot;十二、和以天倪：不强行抹平，也不固守人为分别&quot;">​</a></h4><p>“天”指向自然、自然而然，“倪”涉及端绪、分际。因而，可先将“和以天倪”理解为：让言说与事物自然呈现的差异、关系和变化相调和。</p><p>这里的“和”不必等于所有意见完全一致，也可以意味着：</p><ul><li>不把不同者强迫变成相同；</li><li>不把已有分别当作永恒边界；</li><li>不只从一己尺度判定一切。</li></ul><p>“所以穷年”将这种言说方式放入持续的生活之中。卮言不是偶尔说一句玄妙的话，而是怎样长久地言说、理解与回应。</p><p>“天倪”的具体内涵存在解释差异，上述理解用于把握语境，不作为排除其他训释的固定定义。</p><h4 id="十三、不言则齐-语言一旦说出-就形成分别" tabindex="-1">十三、不言则齐：语言一旦说出，就形成分别 <a class="header-anchor" href="#十三、不言则齐-语言一旦说出-就形成分别" aria-label="Permalink to &quot;十三、不言则齐：语言一旦说出，就形成分别&quot;">​</a></h4><blockquote><p>不言则齐，齐与言不齐，言与齐不齐也。</p></blockquote><p>这一组句子简约，训释不完全一致。可以先把握其中的张力：尚未作出言说时，没有这些由言说明确划出的分别；一旦说出，就有了此与彼、是与非。</p><p>即使说“万物齐一”，也已经提出一个说法。这个说法仍然可能与其他说法相区别，被人赞同或反对，甚至被当作固定主张。</p><p>因而，不能轻易认为：只要宣布“一切平等”，就已经超越了一切分别。</p><p>同样，也不宜认为“不言则齐”证明沉默永远优于言说。这里揭示的是<strong>语言与齐同之间的困难</strong>，不是给沉默颁发最终正确的资格。</p><h4 id="十四、言无言-能够说话-却不把所说当作全部" tabindex="-1">十四、言无言：能够说话，却不把所说当作全部 <a class="header-anchor" href="#十四、言无言-能够说话-却不把所说当作全部" aria-label="Permalink to &quot;十四、言无言：能够说话，却不把所说当作全部&quot;">​</a></h4><blockquote><p>故曰：“言无言。”</p></blockquote><p>贯通上文，“言无言”可以理解为一种言说方式：说话，但不以自己的话封闭对象；作出表达，但不把表达当作不可更改的实在。</p><p>作为帮助理解的引申，可以想到：</p><ul><li>说明某种判断，同时承认它有适用条件；</li><li>借助概念，但不把概念等同于所指的一切；</li><li>回应别人，但不以争赢为唯一目的。</li></ul><p>这些不是原文逐项列出的规则。</p><p>关键不在于把每句话说得模糊，而在于言说具有开放性，能够继续接受情境与理解的修正。</p><h4 id="十五、终身言与终身不言-发声多少-不是唯一标准" tabindex="-1">十五、终身言与终身不言：发声多少，不是唯一标准 <a class="header-anchor" href="#十五、终身言与终身不言-发声多少-不是唯一标准" aria-label="Permalink to &quot;十五、终身言与终身不言：发声多少，不是唯一标准&quot;">​</a></h4><blockquote><p>终身言，未尝言；终身不言，未尝不言。</p></blockquote><p>两句看似矛盾，是因为前后的“言”不能只按同一种意义机械相加。</p><p>一种贯通上文的理解是：</p><table tabindex="0"><thead><tr><th>表面的言说状态</th><th>更深一层的区别</th></tr></thead><tbody><tr><td>终身言</td><td>虽持续说话，却未固执地树立自己的说法</td></tr><tr><td>终身不言</td><td>虽未发声，却未必因此超出表达与立场</td></tr></tbody></table><p>沉默也可能表达态度，也可能含有固执。因此，说得多，不必然被语言束缚；说得少，也不必然已经自在。</p><p>原文打破“言／不言”的简单对立，使读者转而考察：说话或沉默时，是否仍执着于一种自我中心的立场？</p><p>不过，这组句子具有多义性，以上不宜当作唯一的逐字定译。</p><h4 id="十六、有自也而可-相反判断-各有其所从" tabindex="-1">十六、有自也而可：相反判断，各有其所从 <a class="header-anchor" href="#十六、有自也而可-相反判断-各有其所从" aria-label="Permalink to &quot;十六、有自也而可：相反判断，各有其所从&quot;">​</a></h4><blockquote><p>有自也而可，有自也而不可；有自也而然，有自也而不然。</p></blockquote><p>“有自”强调有所从、有出发点。同一事物，在不同条件、关系或立场中，可能得到相反判断。</p><p>相反的判断并不是凭空出现的，但“各有其所从”不等于：</p><ul><li>各种判断同样有充分根据；</li><li>错误与正确毫无区别；</li><li>所有行为都应被认可。</li></ul><p>它首先要求我们：<strong>不要只宣布结论，还要追问结论怎样形成。</strong></p><h4 id="十七、然于然、可于可-追问判断如何成立" tabindex="-1">十七、然于然、可于可：追问判断如何成立 <a class="header-anchor" href="#十七、然于然、可于可-追问判断如何成立" aria-label="Permalink to &quot;十七、然于然、可于可：追问判断如何成立&quot;">​</a></h4><blockquote><p>恶乎然？然于然；恶乎不然？不然于不然。<br> 恶乎可？可于可；恶乎不可？不可于不可。</p></blockquote><p>这些句子表面像重复，实际上可以把注意力从对象转向认定过程：某物被称为“然”或“可”，与它被怎样理解、怎样判定有关。</p><p>联系前文“同于己为是之，异于己为非之”，可以看到层层推进：</p><ul><li>前文揭露，人可能把“与我相同”当作正确依据；</li><li>此处进一步提醒，被认定为正确、可接受的东西，也需要检验其认定方式。</li></ul><p>不要把“已经被这样称呼”，直接当作“只能如此”的证明。</p><p>但也不必由此宣布外在事物完全由语言任意创造。原文在这里讨论判断的成立，不是在给出一套完整的语言建构理论。</p><h4 id="十八、无物不然-无物不可-不是给一切行为开脱" tabindex="-1">十八、无物不然，无物不可：不是给一切行为开脱 <a class="header-anchor" href="#十八、无物不然-无物不可-不是给一切行为开脱" aria-label="Permalink to &quot;十八、无物不然，无物不可：不是给一切行为开脱&quot;">​</a></h4><blockquote><p>物固有所然，物固有所可。无物不然，无物不可。</p></blockquote><p>前面的“有所”很重要。联系这一限定，可理解为：事物都有在某种关系或角度中被理解为如此、被认可的方面。</p><p>这有助于打破单一尺度的垄断，却不能改写成“一切事物永远正确，一切行为都可以做”。</p><p>若将这一提醒引申到现代伦理讨论，对行为的判断仍需考虑实际伤害、具体条件、不同当事人的处境，以及理由是否充分。</p><p>这是现代阅读中的必要辨析，不是原文列出的伦理检查表。</p><p>本段松动的是<strong>绝对化的判断姿态</strong>，不是取消一切责任与差别。</p><h4 id="十九、孰得其久-固定的话-如何面对变化的世界" tabindex="-1">十九、孰得其久：固定的话，如何面对变化的世界？ <a class="header-anchor" href="#十九、孰得其久-固定的话-如何面对变化的世界" aria-label="Permalink to &quot;十九、孰得其久：固定的话，如何面对变化的世界？&quot;">​</a></h4><blockquote><p>非卮言日出，和以天倪，孰得其久！</p></blockquote><p>这一句回到卮言的论述，可以理解为：如果言说不能随情境不断展开，不能与自然的分际相调和，又怎样长久地与变化相应？</p><p>“久”不宜径释为个人肉身长生。联系上下文，将其理解为言说与生活的持续相应，更便于贯通本段。</p><p>事物在变，关系在变，理解也可能在变。长久不一定靠永远重复同一句话，反而可能依赖能够修正、转换与重新表达。</p><h4 id="二十、不同形相禅-变化不止于意见-也涉及万物" tabindex="-1">二十、不同形相禅：变化不止于意见，也涉及万物 <a class="header-anchor" href="#二十、不同形相禅-变化不止于意见-也涉及万物" aria-label="Permalink to &quot;二十、不同形相禅：变化不止于意见，也涉及万物&quot;">​</a></h4><blockquote><p>万物皆种也，以不同形相禅，始卒若环，莫得其伦。</p></blockquote><p>原文从人的判断转向万物的生成变化。“相禅”强调接续、递代，“始卒若环”强调终始相接。</p><p>一种形态的终结，可以与另一种形态的出现相连；从整体看，变化并非总有一个可轻易截定的绝对起点。</p><p>“万物皆种”的具体解释存在分歧，不宜直接改写成现代生物学命题，尤其不能说：</p><ul><li>庄子在这里提出了现代进化论；</li><li>所有物种都能任意相互变成；</li><li>这种环形变化已经得到科学验证。</li></ul><p>这里属于古代生成变化论的表达，重在使人松开对固定形态与终始边界的执着。</p><h4 id="二十一、莫得其伦-不把局部次序当作完整根源" tabindex="-1">二十一、莫得其伦：不把局部次序当作完整根源 <a class="header-anchor" href="#二十一、莫得其伦-不把局部次序当作完整根源" aria-label="Permalink to &quot;二十一、莫得其伦：不把局部次序当作完整根源&quot;">​</a></h4><p>“莫得其伦”可以联系整个变化过程的次序、脉络难以穷尽来理解。</p><p>它不必意味着世界完全无序、什么都无法认识。更适合的提醒是：人能认识某些变化关系，却未必因此已经掌握全部终始与根源。</p><p><strong>能够说明一部分，不等于已经抵达最终根据。</strong></p><p>这一理解保留认识的可能，也警惕将局部解释封闭为完整答案。</p><h4 id="二十二、天均者-天倪也-调和并不取消差异" tabindex="-1">二十二、天均者，天倪也：调和并不取消差异 <a class="header-anchor" href="#二十二、天均者-天倪也-调和并不取消差异" aria-label="Permalink to &quot;二十二、天均者，天倪也：调和并不取消差异&quot;">​</a></h4><blockquote><p>是谓天均。天均者，天倪也。</p></blockquote><p>原文把天均与天倪联系起来。为了阅读，可以暂作如下侧重点区分：</p><ul><li><strong>天倪</strong>：强调自然呈现的端绪、分际；</li><li><strong>天均</strong>：强调差异与变化中的自然调和。</li></ul><p>这个区分只是阅读上的帮助，不必视为两个概念各自固定、互不重叠的定义。</p><p>自然的调和，不是把万物压成同一个形状，因为上文明确说“不同形相禅”。</p><p>差异仍然存在，变化仍然发生；需要放下的是人为尺度对一切的强行规定。</p><h3 id="本段合读·接受、分量与开放性" tabindex="-1">本段合读·接受、分量与开放性 <a class="header-anchor" href="#本段合读·接受、分量与开放性" aria-label="Permalink to &quot;本段合读·接受、分量与开放性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>言说方式</th><th>所回应的问题</th><th>需要避免的危险</th></tr></thead><tbody><tr><td>寓言</td><td>听者可能先拒绝言者与异己意见</td><td>把故事当作不需检验的暗示</td></tr><tr><td>重言</td><td>言说需要可信的识见与分量</td><td>把名号、年齿当作永远正确的权威</td></tr><tr><td>卮言</td><td>情境、判断与万物持续变化</td><td>把任何说法固定成不可修正的尺度</td></tr></tbody></table><p>三言可以相互配合：</p><p><strong>借外论说，打开接受的可能；借重识见，使讨论有所依据；保持言说的开放，避免依据重新凝固为执著。</strong></p><p>听话，不要只问“他是否同意我”；尊重言说，也不要只问“他是谁”。还应当问：</p><ul><li>这番话有什么根据？</li><li>它是否看清条理与本末？</li><li>我的既有立场能否接受检验？</li><li>已经成立的说法，是否仍能回应变化？</li></ul><p>这只是对本段的归纳，不代替对全篇各则寓言的具体理解。</p><h3 id="思想参照·与其他篇章对读" tabindex="-1">思想参照·与其他篇章对读 <a class="header-anchor" href="#思想参照·与其他篇章对读" aria-label="Permalink to &quot;思想参照·与其他篇章对读&quot;">​</a></h3><table tabindex="0"><thead><tr><th>本段内容</th><th>可参照篇章</th><th>联系与区别</th></tr></thead><tbody><tr><td>与己同则应，异于己则反</td><td>《齐物论》对成心的反省</td><td>既有立场可能先行决定判断，仍需分别理解语境</td></tr><tr><td>藉外论之</td><td>《外物》涸辙之鲋</td><td>庄周借鱼的回应，使监河侯的承诺与眼前困境形成反差</td></tr><tr><td>名号不保证言说与行为正确</td><td>《外物》儒以《诗》《礼》发冢</td><td>熟悉经典、拥有身份，不自动保证正当；本段更侧重识见依据</td></tr><tr><td>年长不等于不可修正</td><td>《则阳》蘧伯玉六十化</td><td>长久经验可以表现为持续修正，而非固守旧说</td></tr><tr><td>寓言、重言、卮言</td><td>《天下》对庄周言说的描述</td><td>可比较三言的功能，不将不同语境强行合并</td></tr><tr><td>和以天倪</td><td>《齐物论》有关天倪的论述</td><td>都可联系不被僵硬是非束缚来读，具体表达仍需辨析</td></tr><tr><td>然于然、可于可</td><td>《齐物论》有关然与可的段落</td><td>文字与主题接近，适合对读判断如何成立</td></tr><tr><td>言无言</td><td>《外物》得意忘言</td><td>前者侧重不固执的言说，后者侧重言与意、工具与目的</td></tr><tr><td>不言未必超出言</td><td>《则阳》言默不足以载</td><td>沉默不自动成为最终答案</td></tr><tr><td>始卒若环</td><td>《则阳》对万物生成与根源的追问</td><td>终始与解释不宜被轻易封闭</td></tr></tbody></table><blockquote><p>这些联系用于阅读比较，不代表各篇原句完全同义，也不据相似内容断定直接的写作关系或完全一致的思想体系。</p></blockquote><h3 id="本段核心句对照" tabindex="-1">本段核心句对照 <a class="header-anchor" href="#本段核心句对照" aria-label="Permalink to &quot;本段核心句对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>核心句</th><th>阅读重点</th><th>应避免的误读</th></tr></thead><tbody><tr><td>寓言十九，藉外论之</td><td>借外改变表达位置</td><td>寓言只是编故事；人物之言都是作者定论</td></tr><tr><td>亲父誉之，不若非其父者也</td><td>关系影响话语的接受</td><td>父亲必定偏私；外人必定公正</td></tr><tr><td>与己同则应，不与己同则反</td><td>检验以同异代替根据的倾向</td><td>赞同者必对，反对者必错</td></tr><tr><td>重言十七，所以己言也</td><td>借重言说的分量，反省轻率争言</td><td>重言就是重复；权威一出便不许讨论</td></tr><tr><td>年先矣……是非先也</td><td>年龄与识见不能直接等同</td><td>古人永远正确；年老便没有价值</td></tr><tr><td>卮言日出，和以天倪</td><td>言说随情境展开，与自然分际相调和</td><td>卮言就是随意改口或一味迎合</td></tr><tr><td>言无言</td><td>表达而不以言辞封闭理解</td><td>不出声便已超越语言</td></tr><tr><td>有自也而可，有自也而不可</td><td>相反判断各有其所从</td><td>所有判断同样可靠</td></tr><tr><td>无物不然，无物不可</td><td>联系“有所”，理解认可的方面与条件</td><td>一切行为都正当</td></tr><tr><td>不同形相禅，始卒若环</td><td>万物形态递代，终始相接</td><td>古代变化论就是现代进化论</td></tr><tr><td>天均者，天倪也</td><td>自然调和与自然分际相联系</td><td>调和就是抹平所有差异</td></tr></tbody></table><h2 id="二、孔子六十化·自我修正与前见" tabindex="-1">二、孔子六十化·自我修正与前见 <a class="header-anchor" href="#二、孔子六十化·自我修正与前见" aria-label="Permalink to &quot;二、孔子六十化·自我修正与前见&quot;">​</a></h2><h3 id="原文-1" tabindex="-1">原文 <a class="header-anchor" href="#原文-1" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',164)),i(e,{sections:g,glossary:u,"default-mode":"classic","aria-label":"寓言·孔子六十化 原文"}),t[7]||(t[7]=a("blockquote",null,[a("p",null,"**文字说明：**本则的孔子是《庄子》中的孔子。「而不敢蘁，立定天下之定」的断句依所据本子，与他本「不敢蘁立」分读不同；「谢之」的所指亦有异说。以下解释用于贯通语境，不作定论。")],-1)),t[8]||(t[8]=a("h3",{id:"生僻字词",tabindex:"-1"},[n("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),i(d,{items:m}),t[9]||(t[9]=a("h3",{id:"核心句引读",tabindex:"-1"},[n("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),i(r,{lines:b}),t[10]||(t[10]=s('<h3 id="六十化-判断的坐标在移动" tabindex="-1">六十化：判断的坐标在移动 <a class="header-anchor" href="#六十化-判断的坐标在移动" aria-label="Permalink to &quot;六十化：判断的坐标在移动&quot;">​</a></h3><p>一则简短的对话，先由庄子提出一个说法，再由惠子给出另一种解释，最后又由庄子推翻惠子的解释。三个人说的其实是同一件事：一个人怎样和自己过去的判断相处。</p><p>「始时所是，卒而非之」并不稀奇，稀奇的是「六十」二字：到了六十岁还在改。通常把年长与定见连在一起，这里却把岁数与变化连在一起。变化不是晚年的失守，而是六十年来一直在做的事。</p><p>「未知今之所谓是之非五十九非也」更进一步。它不是说一切判断都不可靠，而是提醒：连「现在这个是对的」这句话本身，也可能在下一个年头被重新放到天秤上。</p><h3 id="勤志服知-一个漂亮的解释-为什么不够" tabindex="-1">勤志服知：一个漂亮的解释，为什么不够 <a class="header-anchor" href="#勤志服知-一个漂亮的解释-为什么不够" aria-label="Permalink to &quot;勤志服知：一个漂亮的解释，为什么不够&quot;">​</a></h3><p>惠子的解释很体面：那是勤勉立志、从事于知。把不断修正说成求知的结果，谁也不能说它错。</p><p>但庄子说「孔子谢之矣，而其未之尝言也」——对此不再申说。真正的改过者不忙于解释自己为什么改。一旦把变化解释成一种成就，变化本身就成了新的可夸之物。</p><h3 id="直服人之口-口服与心服之间" tabindex="-1">直服人之口：口服与心服之间 <a class="header-anchor" href="#直服人之口-口服与心服之间" aria-label="Permalink to &quot;直服人之口：口服与心服之间&quot;">​</a></h3><p>后半段转入言说的效果。「鸣而当律，言而当法」已经很高：发声合于音律，说话合于法度。但接着一句就把它压低——「利义陈乎前，而好恶是非直服人之口而已矣」：把利与义摆出来，用是非好恶去说服，得到的也只是嘴上的服从。</p><p>真正的标准在后面：「使人乃以心服而不敢蘁」。心服与不敢违逆，表面结果相同，内里截然相反。一个是关系，一个是压制。</p><h3 id="本段要点" tabindex="-1">本段要点 <a class="header-anchor" href="#本段要点" aria-label="Permalink to &quot;本段要点&quot;">​</a></h3><ul><li>变化不等于失守；六十岁仍在修正，是这一则给出的正面形象。</li><li>把「我在进步」当作新资本，恰恰是变化的终止。</li><li>说服的成色要看心服还是口服，而这从外部往往看不出来。</li></ul><h2 id="三、曾子再仕·俸禄与养亲" tabindex="-1">三、曾子再仕·俸禄与养亲 <a class="header-anchor" href="#三、曾子再仕·俸禄与养亲" aria-label="Permalink to &quot;三、曾子再仕·俸禄与养亲&quot;">​</a></h2><h3 id="原文-2" tabindex="-1">原文 <a class="header-anchor" href="#原文-2" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',14)),i(e,{sections:c,glossary:x,"default-mode":"classic","aria-label":"寓言·曾子再仕 原文"}),t[11]||(t[11]=a("blockquote",null,[a("p",null,[a("strong",null,"文字说明："),n("「三千锺」依所据本子作锺（容器量名），与他本作「钟」同指厚禄；「不洎」「无所县其罪」的训释与句读均有异说。以下按大意疏解，不将一种解释定为一尊。")])],-1)),t[12]||(t[12]=a("h3",{id:"生僻字词-1",tabindex:"-1"},[n("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),i(d,{items:q}),t[13]||(t[13]=a("h3",{id:"核心句引读-1",tabindex:"-1"},[n("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),i(r,{lines:k}),t[14]||(t[14]=s('<h3 id="乐与悲不在数目" tabindex="-1">乐与悲不在数目 <a class="header-anchor" href="#乐与悲不在数目" aria-label="Permalink to &quot;乐与悲不在数目&quot;">​</a></h3><p>曾子的两句话构成一个极干净的对照：三釜很薄，心却乐；三千锺极厚，心却悲。差别只有一个——「及亲」与「不及亲」。</p><p>所以这不是关于俸禄的故事，而是关于「来得及」的故事。俸禄多少可以比较，能不能及于亲却不能补偿。厚禄换不回一次赶上的机会。</p><h3 id="既已县矣-孔子的判断为何不近人情" tabindex="-1">既已县矣：孔子的判断为何不近人情 <a class="header-anchor" href="#既已县矣-孔子的判断为何不近人情" aria-label="Permalink to &quot;既已县矣：孔子的判断为何不近人情&quot;">​</a></h3><p>弟子问：这样算不算已经无所牵累？孔子答「既已县矣」——仍有系累。</p><p>这个回答看似苛刻：一个为亲而悲的人，怎么还被说成有所系？但接着的反问给了理由：「夫无所县者，可以有哀乎？」真正无所系累的人，不会被俸禄与往事牵动到这种程度。</p><p>孔子没有否定曾子的悲，只是指出悲本身也是一条系着的线。承认它，比假装已经放下更诚实。</p><h3 id="雀蚊虻相过乎前" tabindex="-1">雀蚊虻相过乎前 <a class="header-anchor" href="#雀蚊虻相过乎前" aria-label="Permalink to &quot;雀蚊虻相过乎前&quot;">​</a></h3><p>最后一句是整则的尺度：「彼视三釜、三千锺，如观雀蚊虻相过乎前也。」在那种人眼里，薄禄厚禄都只是眼前一掠而过的飞虫。</p><p>这句话既可以读作境界，也可以读作提醒：把俸禄看成飞虫，并不等于不必领俸禄、不必养家。尺度变了，事务还在。</p><h3 id="本段要点-1" tabindex="-1">本段要点 <a class="header-anchor" href="#本段要点-1" aria-label="Permalink to &quot;本段要点&quot;">​</a></h3><ul><li>俸禄的轻重与心的乐悲，不是同一条刻度。</li><li>「来得及」是一种不能用后来之物补偿的条件。</li><li>承认自己仍有所系，是走向无所系的第一步，不是失败。</li></ul><h2 id="四、颜成子游·九年之序与两端之问" tabindex="-1">四、颜成子游·九年之序与两端之问 <a class="header-anchor" href="#四、颜成子游·九年之序与两端之问" aria-label="Permalink to &quot;四、颜成子游·九年之序与两端之问&quot;">​</a></h2><h3 id="原文-3" tabindex="-1">原文 <a class="header-anchor" href="#原文-3" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',14)),i(e,{sections:f,glossary:_,"default-mode":"classic","aria-label":"寓言·颜成子游 原文"}),t[15]||(t[15]=a("blockquote",null,[a("p",null,[a("strong",null,"文字说明："),n("「劝公以其私，死也有自也」的句读与「私」字（他本或作「和」）都有异说；「鬼入」「物」「来」「人据」的训释亦不统一。本则后半连续四组「若之何其……」，句句是问，不句句是断。")])],-1)),t[16]||(t[16]=a("h3",{id:"生僻字词-2",tabindex:"-1"},[n("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),i(d,{items:z}),t[17]||(t[17]=a("h3",{id:"核心句引读-2",tabindex:"-1"},[n("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),i(r,{lines:P}),t[18]||(t[18]=s('<h3 id="九年的次序-读作次序就好" tabindex="-1">九年的次序，读作次序就好 <a class="header-anchor" href="#九年的次序-读作次序就好" aria-label="Permalink to &quot;九年的次序，读作次序就好&quot;">​</a></h3><p>一年而野、二年而从……九年而大妙，读起来像一份进度表。但它更像一段自述：每一年去掉一点什么，越往后越难命名。</p><p>值得注意的是它从「野」开始——第一年不是获得高妙，而是回到质朴。次序的第一步是减法。</p><p>也不必把九年当作人人都要走的年限。它是一个人的说法，不是考核标准。</p><h3 id="鬼入与天成-说不清的地方就说不清" tabindex="-1">鬼入与天成：说不清的地方就说不清 <a class="header-anchor" href="#鬼入与天成-说不清的地方就说不清" aria-label="Permalink to &quot;鬼入与天成：说不清的地方就说不清&quot;">​</a></h3><p>第六年「鬼入」、第七年「天成」，都是极难注的词语。旧注有「鬼神来入」之说，也有别的解释。硬要给它一个现代对应，反而失真。</p><p>这一段的价值也许正在这里：它承认有些境地只能用词点一下，不能展开成理论。</p><h3 id="四组「若之何其」-两端都不作证" tabindex="-1">四组「若之何其」：两端都不作证 <a class="header-anchor" href="#四组「若之何其」-两端都不作证" aria-label="Permalink to &quot;四组「若之何其」：两端都不作证&quot;">​</a></h3><p>后半段连问：不知其终，能说没有命吗？不知其始，能说有命吗？有相应，能说无鬼吗？无相应，能说有鬼吗？</p><p>四问的句式完全相同，方向却相反。这不是要证明命与鬼不存在，也不是要证明它们存在，而是拒绝在没有根据的地方下判断。</p><p>这种写法与篇首「卮言日出」正相通：言说随问而展开，不急于封口。</p><h3 id="本段要点-2" tabindex="-1">本段要点 <a class="header-anchor" href="#本段要点-2" aria-label="Permalink to &quot;本段要点&quot;">​</a></h3><ul><li>修学的第一步常是减去浮华，而不是增加本领。</li><li>有些境地只能点名，不宜系统化。</li><li>两端都提出、都不裁定，是一种自觉的方法，而非含糊。</li></ul><h2 id="五、众罔两问景·所待与随动" tabindex="-1">五、众罔两问景·所待与随动 <a class="header-anchor" href="#五、众罔两问景·所待与随动" aria-label="Permalink to &quot;五、众罔两问景·所待与随动&quot;">​</a></h2><h3 id="原文-4" tabindex="-1">原文 <a class="header-anchor" href="#原文-4" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',15)),i(e,{sections:j,glossary:w,"default-mode":"classic","aria-label":"寓言·众罔两问景 原文"}),t[19]||(t[19]=a("blockquote",null,[a("p",null,[a("strong",null,"文字说明："),n("「彼，吾所以有待邪，而况乎以无有待者乎」中「无有待」依所据本子，他本或作「以有待者」；「罔两」「搜搜」「强阳」的训释亦不统一。此则义理与他书所载略同而文句有异，不宜互校成一种「标准文本」。")])],-1)),t[20]||(t[20]=a("h3",{id:"生僻字词-3",tabindex:"-1"},[n("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),i(d,{items:T}),t[21]||(t[21]=a("h3",{id:"核心句引读-3",tabindex:"-1"},[n("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),i(r,{lines:S}),t[22]||(t[22]=s('<h3 id="影子不知道自己为什么动" tabindex="-1">影子不知道自己为什么动 <a class="header-anchor" href="#影子不知道自己为什么动" aria-label="Permalink to &quot;影子不知道自己为什么动&quot;">​</a></h3><p>罔两（影外微阴）问影子：刚才低头现在仰头，刚才束发现在披发，刚才坐现在起，刚才走现在停——为什么？</p><p>影子的回答是「予有而不知其所以」：我有这些变化，却不知道其中缘故。这句坦白很重要。它没有说「我不知道，所以都一样」，而是承认自己正处在一条看不清起点的链条里。</p><h3 id="蜩甲与蛇蜕-像-而不是" tabindex="-1">蜩甲与蛇蜕：像，而不是 <a class="header-anchor" href="#蜩甲与蛇蜕-像-而不是" aria-label="Permalink to &quot;蜩甲与蛇蜕：像，而不是&quot;">​</a></h3><p>「予，蜩甲也，蛇蜕也，似之而非也。」蝉蜕像蝉，蛇蜕像蛇，形状还在，本体已去。影与形的关系正是如此：形动影随，但影不是形。</p><p>这个比喻同时也限定了它自己——凡是比喻，都有「似之而非」的成分。</p><h3 id="把追问推上一层" tabindex="-1">把追问推上一层 <a class="header-anchor" href="#把追问推上一层" aria-label="Permalink to &quot;把追问推上一层&quot;">​</a></h3><p>「彼，吾所以有待邪，而况乎以无有待者乎！」影子承认自己有所待（待形、待光），于是把问题推向那个也许并不有待的东西。</p><p>问题到这里没有答案，也不必急着给答案。后面只说：「彼来则我与之来，彼往则我与之往。」随动而动，不自主，也无须自主。</p><p>末句「强阳者，又何以有问乎」既像反问，也像自嘲：一切都在动，问「为什么动」本身就落在了动的里面。</p><h3 id="本段要点-3" tabindex="-1">本段要点 <a class="header-anchor" href="#本段要点-3" aria-label="Permalink to &quot;本段要点&quot;">​</a></h3><ul><li>承认不知道缘故，比编一个缘故更接近实情。</li><li>影随形动，是关系，不是因果链上的第一个推动者。</li><li>追问可以向上推，但不必要求每一层都有一个落地的答案。</li></ul><h2 id="六、阳子居见老聃·神态与争席" tabindex="-1">六、阳子居见老聃·神态与争席 <a class="header-anchor" href="#六、阳子居见老聃·神态与争席" aria-label="Permalink to &quot;六、阳子居见老聃·神态与争席&quot;">​</a></h2><h3 id="原文-5" tabindex="-1">原文 <a class="header-anchor" href="#原文-5" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',14)),i(e,{sections:A,glossary:C,"default-mode":"classic","aria-label":"寓言·阳子居见老聃 原文"}),t[23]||(t[23]=a("blockquote",null,[a("p",null,[a("strong",null,"文字说明："),n("「请问其故」依所据本子，他本或作「请问其过」；「睢睢盱盱」的具体所指有异说。「其反也，舍者与之争席矣」是本则的落点，不可读成受辱。")])],-1)),t[24]||(t[24]=a("h3",{id:"生僻字词-4",tabindex:"-1"},[n("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-4","aria-label":'Permalink to "生僻字词"'},"​")],-1)),i(d,{items:D}),t[25]||(t[25]=a("h3",{id:"核心句引读-4",tabindex:"-1"},[n("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),i(r,{lines:V}),t[26]||(t[26]=s(`<h3 id="一次不解释的否定" tabindex="-1">一次不解释的否定 <a class="header-anchor" href="#一次不解释的否定" aria-label="Permalink to &quot;一次不解释的否定&quot;">​</a></h3><p>老子在梁地遇见阳子居，半路上仰天而叹：「始以汝为可教，今不可也。」没有说理由。</p><p>阳子居的反应是「不答」。被这样否定而不辩解，是很难的：辩解本身就是在证明「我值得教」。他先把这一口气放下，然后「至舍，进盥漱巾栉，脱屦户外，膝行而前」——执礼再问。</p><h3 id="问题不在道理-在气息" tabindex="-1">问题不在道理，在气息 <a class="header-anchor" href="#问题不在道理-在气息" aria-label="Permalink to &quot;问题不在道理，在气息&quot;">​</a></h3><p>老子的回答不是纠他的观点，而是纠他的神态：「而睢睢盱盱，而谁与居！」那副眼神与姿态，让人难以靠近。</p><p>接着两句引自《老子》：「大白若辱，盛德若不足。」最白的好似含垢，最盛的德好似不足。真正充实的人不必把「我很充实」显示出来；一显示，气息就变了。</p><h3 id="争席-恭敬的反面是亲近" tabindex="-1">争席：恭敬的反面是亲近 <a class="header-anchor" href="#争席-恭敬的反面是亲近" aria-label="Permalink to &quot;争席：恭敬的反面是亲近&quot;">​</a></h3><p>结尾是全篇最有画面感的一笔。初来时，「舍者迎将其家，公执席，妻执巾栉，舍者避席，炀者避灶」——人人让位、处处侍奉。那种恭敬里，其实全是距离。</p><p>等到他回来，「舍者与之争席矣」——旅舍的人敢和他争座位了。这不是失了体面，而是从「不可接近」变成了「可以相处」。</p><h3 id="本段要点-4" tabindex="-1">本段要点 <a class="header-anchor" href="#本段要点-4" aria-label="Permalink to &quot;本段要点&quot;">​</a></h3><ul><li>被否定而不急于自辩，是把问题听进去的前提。</li><li>需要纠正的常常不是观点，而是整个人的气息。</li><li>被人争席，往往比被人让席更接近真实的关系。</li></ul><h2 id="三至六则·阶段性脉络" tabindex="-1">三至六则·阶段性脉络 <a class="header-anchor" href="#三至六则·阶段性脉络" aria-label="Permalink to &quot;三至六则·阶段性脉络&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第二则·孔子六十化</span></span>
<span class="line"><span>    六十岁仍在改</span></span>
<span class="line"><span>    → 始是而卒非</span></span>
<span class="line"><span>    → 把「我在进步」当资本，反而停止</span></span>
<span class="line"><span>    → 口服不等于心服</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第三则·曾子再仕</span></span>
<span class="line"><span>    三釜而乐，三千锺而悲</span></span>
<span class="line"><span>    → 差别在「来得及」</span></span>
<span class="line"><span>    → 孔子：仍有所系</span></span>
<span class="line"><span>    → 无所系者视厚薄如飞虫</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第四则·颜成子游</span></span>
<span class="line"><span>    一年而野 …… 九年而大妙</span></span>
<span class="line"><span>    → 第一步是减法</span></span>
<span class="line"><span>    → 鬼入、天成，只能点名</span></span>
<span class="line"><span>    → 命与鬼：两端都问，都不裁定</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第五则·罔两问景</span></span>
<span class="line"><span>    影子为何忽俯忽仰</span></span>
<span class="line"><span>    → 予有而不知其所以</span></span>
<span class="line"><span>    → 蜩甲、蛇蜕，似之而非</span></span>
<span class="line"><span>    → 有所待，且把追问推上一层</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第六则·阳子居</span></span>
<span class="line"><span>    一句不解释的否定</span></span>
<span class="line"><span>    → 不答，执礼再问</span></span>
<span class="line"><span>    → 问题在「睢睢盱盱」的气息</span></span>
<span class="line"><span>    → 舍者与之争席：恭敬的反面是亲近</span></span></code></pre></div><h3 id="阶段性三问" tabindex="-1">阶段性三问 <a class="header-anchor" href="#阶段性三问" aria-label="Permalink to &quot;阶段性三问&quot;">​</a></h3><h4 id="第一问-我是在改变-还是在表演改变" tabindex="-1">第一问：我是在改变，还是在表演改变？ <a class="header-anchor" href="#第一问-我是在改变-还是在表演改变" aria-label="Permalink to &quot;第一问：我是在改变，还是在表演改变？&quot;">​</a></h4><p>六十化与曾子再仕都指向同一件事：真正在变的人，不忙着说明自己变了。</p><h4 id="第二问-我要的是被服从-还是被理解" tabindex="-1">第二问：我要的是被服从，还是被理解？ <a class="header-anchor" href="#第二问-我要的是被服从-还是被理解" aria-label="Permalink to &quot;第二问：我要的是被服从，还是被理解？&quot;">​</a></h4><p>「直服人之口」与「以心服」的分别，在这一组故事里反复出现。</p><h4 id="第三问-我与人之间-是距离-还是关系" tabindex="-1">第三问：我与人之间，是距离，还是关系？ <a class="header-anchor" href="#第三问-我与人之间-是距离-还是关系" aria-label="Permalink to &quot;第三问：我与人之间，是距离，还是关系？&quot;">​</a></h4><p>从避席到争席，只换了一个动作，却换了一种关系。</p><h3 id="阶段性收束" tabindex="-1">阶段性收束 <a class="header-anchor" href="#阶段性收束" aria-label="Permalink to &quot;阶段性收束&quot;">​</a></h3><blockquote><p><strong>修正不必张扬，说服不必强压，亲近不必远敬。三者都指向同一个方向：把关系从姿态里救出来。</strong></p></blockquote><p>这是这几则的串读线索，不是全篇唯一主旨。</p><h2 id="全篇脉络·六则阅读地图" tabindex="-1">全篇脉络·六则阅读地图 <a class="header-anchor" href="#全篇脉络·六则阅读地图" aria-label="Permalink to &quot;全篇脉络·六则阅读地图&quot;">​</a></h2><blockquote><p>六则是阅读整理的分段，并非原文固定章节标题。</p><p>本页依所据本子录入：第一则以「言无言」为总纲，其余五则以人物故事递相发明。</p></blockquote><table tabindex="0"><thead><tr><th>段落</th><th>场景或论题</th><th>核心问题</th></tr></thead><tbody><tr><td>一</td><td>寓言、重言、卮言</td><td>言说怎样被接受，又怎样不封死自己？</td></tr><tr><td>二</td><td>孔子六十化</td><td>自我修正到什么程度才算真修？</td></tr><tr><td>三</td><td>曾子再仕</td><td>乐与悲由什么决定？</td></tr><tr><td>四</td><td>颜成子游</td><td>修学有次序吗？两端之问怎样安放？</td></tr><tr><td>五</td><td>众罔两问景</td><td>我在依赖什么？追问能推到哪一层？</td></tr><tr><td>六</td><td>阳子居见老聃</td><td>需要改的是观点，还是整个人的气息？</td></tr></tbody></table><h3 id="一条串读线索" tabindex="-1">一条串读线索 <a class="header-anchor" href="#一条串读线索" aria-label="Permalink to &quot;一条串读线索&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>言之难</span></span>
<span class="line"><span>    寓言：换一个人说</span></span>
<span class="line"><span>    重言：借分量说</span></span>
<span class="line"><span>    卮言：随情境说，不封口</span></span>
<span class="line"><span></span></span>
<span class="line"><span>听之难</span></span>
<span class="line"><span>    与己同则应，不与己同则反</span></span>
<span class="line"><span>    直服人之口，难服人之心</span></span>
<span class="line"><span></span></span>
<span class="line"><span>改之难</span></span>
<span class="line"><span>    六十化：改到六十岁</span></span>
<span class="line"><span>    曾子：来得及与来不及</span></span>
<span class="line"><span>    颜成子游：减法在先，说不清的存疑</span></span>
<span class="line"><span></span></span>
<span class="line"><span>待之难</span></span>
<span class="line"><span>    影子有所待，且不知其所以</span></span>
<span class="line"><span>    追问向上推，不必层层落地</span></span>
<span class="line"><span></span></span>
<span class="line"><span>处之难</span></span>
<span class="line"><span>    睢睢盱盱，谁与居</span></span>
<span class="line"><span>    争席取代避席，关系才真正开始</span></span></code></pre></div><p>六则不是一条层层升高的阶梯，而是一组互相照映的追问：</p><p><strong>话怎样说出去，又怎样被接住；人怎样改自己，又怎样与人相处。</strong></p><h2 id="三问解读" tabindex="-1">三问解读 <a class="header-anchor" href="#三问解读" aria-label="Permalink to &quot;三问解读&quot;">​</a></h2><h3 id="第一问-我的话是被听进去了-还是被挡回来了" tabindex="-1">第一问：我的话是被听进去了，还是被挡回来了？ <a class="header-anchor" href="#第一问-我的话是被听进去了-还是被挡回来了" aria-label="Permalink to &quot;第一问：我的话是被听进去了，还是被挡回来了？&quot;">​</a></h3><p>篇首把这件事拆得很细。寓言是改变说话的位置——不直接说，借他人之口说；重言是借分量——让有分量的人说；卮言是随情境展开，不把话说死。</p><p>三者不是三种文体分类，而是三种「让话有可能被接住」的努力。而接着的一句更冷：「与己同则应，不与己同则反。」听者常常先看这句话合不合自己的意，再决定要不要听内容。</p><p>所以本则的结论不是「要说得更漂亮」，而是承认：言说的效果，一半在说者，一半在接受的条件。承认这一点，才不会把没被听懂全算成对方的问题。</p><h3 id="第二问-我改变的是判断-还是只是换了一套说辞" tabindex="-1">第二问：我改变的是判断，还是只是换了一套说辞？ <a class="header-anchor" href="#第二问-我改变的是判断-还是只是换了一套说辞" aria-label="Permalink to &quot;第二问：我改变的是判断，还是只是换了一套说辞？&quot;">​</a></h3><p>孔子六十化的重点不在「变」，而在「还在变」。六十岁仍在否定自己五十几岁的是，这不是失守，而是没有停下来。</p><p>但紧接着的风险也出现了：一旦把「我在进步」当成新的资本，变化就终止了——从此不再修正，只负责讲述自己如何修正。庄子说「孔子谢之矣，而其未之尝言也」，正是这个意思。</p><p>曾子再仕则给出另一种检验：乐与悲随俸禄而变，说明心仍被牵动。孔子不否认他的悲，只指出那份悲本身也是一条系着的线。</p><h3 id="第三问-我与外物之间-是使用、依赖-还是被规定" tabindex="-1">第三问：我与外物之间，是使用、依赖，还是被规定？ <a class="header-anchor" href="#第三问-我与外物之间-是使用、依赖-还是被规定" aria-label="Permalink to &quot;第三问：我与外物之间，是使用、依赖，还是被规定？&quot;">​</a></h3><p>影子承认「予有而不知其所以」：它有所待，却看不清链条的起点。这不是无能，而是诚实。</p><p>阳子居的故事把这一问落到人际：他最初被恭敬地围着，后来人们敢与他争席。前者是距离，后者才是关系。外物可以是帮助、是条件、是危险、是评价——但一旦它成了我的尺度，我就不再是使用者。</p><h2 id="现代思考与启发" tabindex="-1">现代思考与启发 <a class="header-anchor" href="#现代思考与启发" aria-label="Permalink to &quot;现代思考与启发&quot;">​</a></h2><h3 id="一、表达-先想「谁来说、对谁说」" tabindex="-1">一、表达：先想「谁来说、对谁说」 <a class="header-anchor" href="#一、表达-先想「谁来说、对谁说」" aria-label="Permalink to &quot;一、表达：先想「谁来说、对谁说」&quot;">​</a></h3><p>同一句称赞，父亲说与外人说，效果不同（「亲父不为其子媒」）。这不是教人绕着说话，而是提醒：内容之外，位置也在起作用。</p><p>做产品说明、写方案、给反馈时，先问一句：由谁来说、在什么场合说，这句话才可能被听进去。</p><h3 id="二、沟通-口服与心服要分开验收" tabindex="-1">二、沟通：口服与心服要分开验收 <a class="header-anchor" href="#二、沟通-口服与心服要分开验收" aria-label="Permalink to &quot;二、沟通：口服与心服要分开验收&quot;">​</a></h3><p>「直服人之口而已矣」是一句很好的验收标准。会上没人反对，不等于被说服；指标完成，不等于认同。</p><p>可以增加一个追问：对方是「不敢违逆」，还是「愿意配合」？两者的后续成本完全不同——前者需要持续监督，后者不需要。</p><h3 id="三、成长-警惕「我在进步」成为新资本" tabindex="-1">三、成长：警惕「我在进步」成为新资本 <a class="header-anchor" href="#三、成长-警惕「我在进步」成为新资本" aria-label="Permalink to &quot;三、成长：警惕「我在进步」成为新资本&quot;">​</a></h3><p>把反思做成展示，反思就停了。可以给自己留一条不成文的规定：重要的修正，先不宣布，等它在下一次判断里自然出现。</p><h3 id="四、时间-区分「来得及」与「补得上」" tabindex="-1">四、时间：区分「来得及」与「补得上」 <a class="header-anchor" href="#四、时间-区分「来得及」与「补得上」" aria-label="Permalink to &quot;四、时间：区分「来得及」与「补得上」&quot;">​</a></h3><p>曾子的悲来自「不洎」——不是俸禄不够，而是来不及。生活里有大量事情属于这一类：能补的是钱与物，补不上的是当时在场。</p><p>这条区分能帮人排出优先次序：能被替代的，晚一点没关系；不能被替代的，今天就要在场。</p><h3 id="五、判断-在没有根据处保留疑问" tabindex="-1">五、判断：在没有根据处保留疑问 <a class="header-anchor" href="#五、判断-在没有根据处保留疑问" aria-label="Permalink to &quot;五、判断：在没有根据处保留疑问&quot;">​</a></h3><p>「莫知其所终，若之何其无命也？莫知其所始，若之何其有命也？」这种句式值得学：两端都提出，两端都不裁定。</p><p>它不等于没有立场，而是把「不知道」如实标出来。在信息不足时，明确说出不确定，比给出一个漂亮结论更负责。</p><h3 id="六、关系-从「被让席」到「能争席」" tabindex="-1">六、关系：从「被让席」到「能争席」 <a class="header-anchor" href="#六、关系-从「被让席」到「能争席」" aria-label="Permalink to &quot;六、关系：从「被让席」到「能争席」&quot;">​</a></h3><p>被特别对待，未必是关系好，可能只是距离远。真正的亲近，往往表现为可以开玩笑、可以争座位、可以说不好听的话。</p><p>如果一段关系里始终只有恭敬，值得想一想：是彼此尊重，还是彼此都还没靠近。</p><h3 id="七、言行-改的是气息-不只是措辞" tabindex="-1">七、言行：改的是气息，不只是措辞 <a class="header-anchor" href="#七、言行-改的是气息-不只是措辞" aria-label="Permalink to &quot;七、言行：改的是气息，不只是措辞&quot;">​</a></h3><p>老子批评阳子居的，不是他讲错了什么，而是「睢睢盱盱」。姿态与语气，常常比内容更早被对方接收到。</p><p>想改善沟通，除了改措辞，也可以留意更基本的一层：说话时的姿态，是不是在无声地要求对方仰视。</p><h2 id="关键词索引" tabindex="-1">关键词索引 <a class="header-anchor" href="#关键词索引" aria-label="Permalink to &quot;关键词索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>词条</th><th>所在段</th><th>要点</th></tr></thead><tbody><tr><td>寓言</td><td>一</td><td>借外在人物、他者或情境论说</td></tr><tr><td>重言</td><td>一</td><td>借有分量的言说，仍须实际根据</td></tr><tr><td>卮言</td><td>一</td><td>随情境展开，不把话说死</td></tr><tr><td>和以天倪</td><td>一</td><td>与自然分际相调和</td></tr><tr><td>藉外论之</td><td>一</td><td>改变表达的位置</td></tr><tr><td>亲父不为其子媒</td><td>一</td><td>同一句称赞，说话者不同则接受不同</td></tr><tr><td>与己同则应</td><td>一</td><td>听者先看合不合己意</td></tr><tr><td>是之·非之</td><td>一</td><td>以同异定是非</td></tr><tr><td>耆艾</td><td>一</td><td>年长者；年齿不等于识见</td></tr><tr><td>经纬本末</td><td>一</td><td>有本末条理，不只是记得多</td></tr><tr><td>陈人</td><td>一</td><td>徒具资格而无实见者</td></tr><tr><td>因以曼衍</td><td>一</td><td>随事推衍，不固守一套话</td></tr><tr><td>言无言</td><td>一</td><td>说话而不把所说当作全部</td></tr><tr><td>有自也</td><td>一</td><td>判断各有其所从出</td></tr><tr><td>可·不可</td><td>一</td><td>相反判断各有其成立条件</td></tr><tr><td>万物皆种</td><td>一</td><td>万物各有所生之种</td></tr><tr><td>相禅</td><td>一</td><td>形态递代相续</td></tr><tr><td>若环</td><td>一</td><td>终始相接，找不到绝对起点</td></tr><tr><td>天均</td><td>一</td><td>自然调和，与天倪互训</td></tr><tr><td>六十化</td><td>二</td><td>六十岁而年年更新</td></tr><tr><td>始时所是</td><td>二</td><td>起初认为对的</td></tr><tr><td>勤志服知</td><td>二</td><td>惠子的解释：勤勉求知</td></tr><tr><td>谢之</td><td>二</td><td>对此不再申说</td></tr><tr><td>受才乎大本</td><td>二</td><td>从大本领受才质</td></tr><tr><td>直服人之口</td><td>二</td><td>只是使人嘴上服从</td></tr><tr><td>蘁</td><td>二</td><td>违逆，通「牾」</td></tr><tr><td>定天下之定</td><td>二</td><td>使天下安定者安定</td></tr><tr><td>再仕</td><td>三</td><td>两次出仕</td></tr><tr><td>心再化</td><td>三</td><td>心境再次变化</td></tr><tr><td>三釜</td><td>三</td><td>微薄俸禄</td></tr><tr><td>不洎</td><td>三</td><td>不能及于亲</td></tr><tr><td>无所县其罪</td><td>三</td><td>是否已无所牵挂</td></tr><tr><td>雀蚊虻</td><td>三</td><td>细小之物，一掠而过</td></tr><tr><td>一年而野</td><td>四</td><td>第一年先回到质朴</td></tr><tr><td>鬼入</td><td>四</td><td>深入幽微；训释有异</td></tr><tr><td>天成</td><td>四</td><td>自然天成</td></tr><tr><td>大妙</td><td>四</td><td>深微难名的境地</td></tr><tr><td>历数</td><td>四</td><td>天象岁时之数</td></tr><tr><td>人据</td><td>四</td><td>人所依据</td></tr><tr><td>罔两</td><td>五</td><td>影外微阴</td></tr><tr><td>蜩甲</td><td>五</td><td>蝉蜕，似之而非</td></tr><tr><td>蛇蜕</td><td>五</td><td>蛇蜕皮，与蜩甲并列</td></tr><tr><td>有待</td><td>五</td><td>有所依赖</td></tr><tr><td>强阳</td><td>五</td><td>运动有力之状</td></tr><tr><td>阳子居</td><td>六</td><td>人名，一说即杨朱</td></tr><tr><td>盥漱巾栉</td><td>六</td><td>洗盥之具，写服事之礼</td></tr><tr><td>睢睢盱盱</td><td>六</td><td>直视傲视之状</td></tr><tr><td>大白若辱</td><td>六</td><td>最白好似含垢</td></tr><tr><td>盛德若不足</td><td>六</td><td>德盛而自处如不足</td></tr><tr><td>蹴然</td><td>六</td><td>惊惭不安之状</td></tr><tr><td>争席</td><td>六</td><td>争座位，是关系变近</td></tr></tbody></table><h2 id="核心句速查" tabindex="-1">核心句速查 <a class="header-anchor" href="#核心句速查" aria-label="Permalink to &quot;核心句速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原文</th><th>段</th><th>要点</th></tr></thead><tbody><tr><td>寓言十九，重言十七，卮言日出，和以天倪。</td><td>一</td><td>三种言说方式并列</td></tr><tr><td>亲父不为其子媒。</td><td>一</td><td>说话的位置影响接受</td></tr><tr><td>非吾罪也，人之罪也。</td><td>一</td><td>接受条件也需被考虑</td></tr><tr><td>与己同则应，不与己同则反。</td><td>一</td><td>先看同异，再听内容</td></tr><tr><td>年先矣，而无经纬本末以期年耆者，是非先也。</td><td>一</td><td>年齿不等于识见</td></tr><tr><td>人而无人道，是之谓陈人。</td><td>一</td><td>徒具资格之谓</td></tr><tr><td>不言则齐，齐与言不齐。</td><td>一</td><td>一说即分</td></tr><tr><td>终身言，未尝言；终身不言，未尝不言。</td><td>一</td><td>多少不是唯一标准</td></tr><tr><td>有自也而可，有自也而不可。</td><td>一</td><td>判断各有来由</td></tr><tr><td>无物不然，无物不可。</td><td>一</td><td>不是为一切开脱</td></tr><tr><td>万物皆种也，以不同形相禅，始卒若环。</td><td>一</td><td>形态递代，终始相接</td></tr><tr><td>天均者，天倪也。</td><td>一</td><td>调和而不抹平差异</td></tr><tr><td>孔子行年六十而六十化。</td><td>二</td><td>六十岁仍在改</td></tr><tr><td>始时所是，卒而非之。</td><td>二</td><td>自我修正不是失守</td></tr><tr><td>孔子谢之矣，而其未之尝言也。</td><td>二</td><td>不必忙着解释自己</td></tr><tr><td>言而当法。</td><td>二</td><td>合规矩仍是外在准确</td></tr><tr><td>直服人之口而已矣。</td><td>二</td><td>口服不等于心服</td></tr><tr><td>使人乃以心服而不敢蘁。</td><td>二</td><td>要的是心服</td></tr><tr><td>已乎，已乎！吾且不得及彼乎！</td><td>二</td><td>庄子的叹服</td></tr><tr><td>三釜而心乐……三千锺而不洎，吾心悲。</td><td>三</td><td>乐悲不在数目</td></tr><tr><td>既已县矣！</td><td>三</td><td>仍有所系</td></tr><tr><td>夫无所县者，可以有哀乎？</td><td>三</td><td>无所系者不再被牵动</td></tr><tr><td>如观雀蚊虻相过乎前也。</td><td>三</td><td>厚薄如飞虫一掠</td></tr><tr><td>一年而野。</td><td>四</td><td>第一步是减法</td></tr><tr><td>九年而大妙。</td><td>四</td><td>次序读作次序</td></tr><tr><td>莫知其所终，若之何其无命也？</td><td>四</td><td>不知其终，不下断语</td></tr><tr><td>无以相应也，若之何其有鬼邪？</td><td>四</td><td>两端都问</td></tr><tr><td>予有而不知其所以。</td><td>五</td><td>承认不知缘故</td></tr><tr><td>予，蜩甲也，蛇蜕也，似之而非也。</td><td>五</td><td>像，而不是</td></tr><tr><td>彼来则我与之来，彼往则我与之往。</td><td>五</td><td>随动而动</td></tr><tr><td>强阳者，又何以有问乎！</td><td>五</td><td>一切都在动</td></tr><tr><td>始以汝为可教，今不可也。</td><td>六</td><td>不解释的否定</td></tr><tr><td>阳子居不答。</td><td>六</td><td>不急于自辩</td></tr><tr><td>而睢睢盱盱，而谁与居！</td><td>六</td><td>问题在气息</td></tr><tr><td>大白若辱，盛德若不足。</td><td>六</td><td>充实不必外显</td></tr><tr><td>舍者与之争席矣！</td><td>六</td><td>恭敬的反面是亲近</td></tr></tbody></table><h2 id="与前篇的呼应" tabindex="-1">与前篇的呼应 <a class="header-anchor" href="#与前篇的呼应" aria-label="Permalink to &quot;与前篇的呼应&quot;">​</a></h2><ul><li><strong>《齐物论》</strong>：本篇的「卮言」与「有自也而可」延续了齐物一路——是非各有其所从，不急于以一方统一另一方。</li><li><strong>《人间世》</strong>：言说的处境与接受条件，与本篇「亲父不为其子媒」「与己同则应」相通。</li><li><strong>《德充符》</strong>：「盛德若不足」与德充于内而不外炫，是同一路数。</li><li><strong>《养生主》</strong>：曾子之悲与「不洎」，可与「可以保身，可以全生」对照——所保全的，也包括来得及。</li><li><strong>《山木》</strong>：处身于人间而保持自持，与本篇阳子居由避席到争席的转向互为参照。</li><li><strong>《知北游》</strong>：颜成子游的四组「若之何其」，与「知者不言，言者不知」共享同一种克制。</li><li><strong>《则阳》</strong>：言默不足以载，侧重议论的限度；本篇「言无言」侧重表达的方式——一在不能尽，一在不封口。</li></ul><p>参读不等于各句完全同义，也不据此确定写作先后与直接影响。</p><h2 id="六则·一句话回顾" tabindex="-1">六则·一句话回顾 <a class="header-anchor" href="#六则·一句话回顾" aria-label="Permalink to &quot;六则·一句话回顾&quot;">​</a></h2><ol><li><strong>三言与言说</strong>：寓言换位置、重言借分量、卮言不封口，而听者常常先看同异。</li><li><strong>孔子六十化</strong>：六十岁仍在改，且不解释自己为什么改。</li><li><strong>曾子再仕</strong>：乐与悲不在俸禄厚薄，在来不来得及。</li><li><strong>颜成子游</strong>：第一步是减去浮华；说不清的，就留着疑问。</li><li><strong>众罔两问景</strong>：有所待而不知其所以，仍可以如实说出。</li><li><strong>阳子居见老聃</strong>：要改的不是话，是那副让人难以靠近的气息。</li></ol><h2 id="一句话读懂《寓言》" tabindex="-1">一句话读懂《寓言》 <a class="header-anchor" href="#一句话读懂《寓言》" aria-label="Permalink to &quot;一句话读懂《寓言》&quot;">​</a></h2><blockquote><p><strong>「寓言十九，重言十七，卮言日出，和以天倪。」</strong></p></blockquote><p>《寓言》开头讲的是说话的方式，往后五则讲的都是这件事的后果：话要有人接得住，人要跟得上自己的判断，关系要经得起靠近。三言不是技巧，而是一种自觉——把话借出去、把分量交出去、把结论留一条缝。</p><h2 id="校读与说明" tabindex="-1">校读与说明 <a class="header-anchor" href="#校读与说明" aria-label="Permalink to &quot;校读与说明&quot;">​</a></h2><h3 id="一、篇目归属" tabindex="-1">一、篇目归属 <a class="header-anchor" href="#一、篇目归属" aria-label="Permalink to &quot;一、篇目归属&quot;">​</a></h3><p><strong>《寓言》为《庄子》第二十七篇，属于杂篇。</strong></p><p>本页不复用他篇的标题、变量或篇目来源。</p><h3 id="二、原文状态" tabindex="-1">二、原文状态 <a class="header-anchor" href="#二、原文状态" aria-label="Permalink to &quot;二、原文状态&quot;">​</a></h3><ul><li>第一则依所提供文本录入，保留其标点与「言无言」等处的句读。</li><li>第二则「而不敢蘁，立定天下之定」依所据本子分读。</li><li>第三则「三千锺」作锺（量名），与他本作「钟」同指厚禄。</li><li>第四则「劝公以其私，死也有自也」依所据本子；他本或作「劝公以其死也，有自也」。</li><li>第五则「彼，吾所以有待邪，而况乎以无有待者乎」依所据本子；他本或作「以有待者」。</li><li>第六则「请问其故」依所据本子；他本或作「请问其过」。</li></ul><h3 id="三、疑难文字" tabindex="-1">三、疑难文字 <a class="header-anchor" href="#三、疑难文字" aria-label="Permalink to &quot;三、疑难文字&quot;">​</a></h3><p>定稿时应选定底本，集中核对：</p><ul><li>第一则「十九」「十七」「卮言」「曼衍」「天均」的训释。</li><li>第二则「勤志服知」「谢之」「蘁」的句读与释义。</li><li>第三则「不洎」「无所县其罪」的句读。</li><li>第四则「物」「来」「鬼入」「劝公」「人据」的训释。</li><li>第五则「罔两」「搜搜」「强阳」的训释。</li><li>第六则「睢睢盱盱」「执席」「炀者」的名物与训释。</li></ul><p>不凭现代引申默默改写正文。</p><h3 id="四、跨篇参读" tabindex="-1">四、跨篇参读 <a class="header-anchor" href="#四、跨篇参读" aria-label="Permalink to &quot;四、跨篇参读&quot;">​</a></h3><ul><li>《齐物论》的「卮言」「天倪」，可与本篇第一则对读。</li><li>《德充符》的德充于内，可与「盛德若不足」参看。</li><li>他书所载罔两问景，文句与本篇有异，宜分别读，不强行互校成一种文本。</li></ul><p>参读不等于各句完全同义，也不据此确定写作先后与直接影响。</p><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><h3 id="本次直接依据" tabindex="-1">本次直接依据 <a class="header-anchor" href="#本次直接依据" aria-label="Permalink to &quot;本次直接依据&quot;">​</a></h3><ul><li>所提供《庄子·寓言》全篇原文（六则）。</li><li>本页分段与解读为阅读整理，非原书章节。</li></ul><h3 id="建议校读材料" tabindex="-1">建议校读材料 <a class="header-anchor" href="#建议校读材料" aria-label="Permalink to &quot;建议校读材料&quot;">​</a></h3><ul><li>郭庆藩《庄子集释》本篇注疏。</li><li>王先谦《庄子集解》本篇。</li><li>陈鼓应《庄子今注今译》本篇。</li><li>通行《老子》第二十八章、四十一章（「大白若辱」「盛德若不足」）。</li></ul><p>各种注本对字句与训释有异，阅读时以所据底本为准。</p><h2 id="全篇最后一问" tabindex="-1">全篇最后一问 <a class="header-anchor" href="#全篇最后一问" aria-label="Permalink to &quot;全篇最后一问&quot;">​</a></h2><p>篇首先说：</p><p><strong>寓言十九，重言十七，卮言日出，和以天倪。</strong></p><p>最后停在：</p><p><strong>舍者与之争席矣！</strong></p><p>从「怎么说」到「怎么相处」，中间隔着五个人物。于是最后可以这样问自己：</p><p><strong>我最近一次被听进去，是因为话说得好，还是因为位置对了？</strong></p><p><strong>我最近一次改变，是真的改了判断，还是只换了说法？</strong></p><p><strong>我有没有把「来不及」的事，错当成「补得上」的事？</strong></p><p><strong>我依赖的那些条件，我知道自己在依赖它们吗？</strong></p><p><strong>与我相处的人，是在让席，还是敢与我争席？</strong></p><h2 id="全篇收束·把话借出去-把自己放低" tabindex="-1">全篇收束·把话借出去，把自己放低 <a class="header-anchor" href="#全篇收束·把话借出去-把自己放低" aria-label="Permalink to &quot;全篇收束·把话借出去，把自己放低&quot;">​</a></h2><p>三言合起来，是一件事：</p><p><strong>把话借出去</strong>——借他人之口，借前人的分量，借当下的情境；不把话攥在自己手里，当作自己的定论。</p><p><strong>把自己放低</strong>——不必把「我在进步」挂在脸上，不必让道理先压倒对方，不必要求别人仰视。</p><p>《寓言》并不许诺说话一定被听懂，也不许诺改变一定被看见。它只是把门槛说清楚：</p><p>能够说出，也承认所说未必被接住；</p><p>能够改变，也承认改变未必被认出；</p><p>能够亲近，也承认亲近要先把姿态放下。</p><p><strong>话可以说得更好，但先要有人接得住；人可以变得更好，但先要不再表演变好。</strong></p>`,114))])}}});export{Y as __pageData,Z as default};
